  /* Enter critical zone */
  rt_mutex_take(&aic_memheaps[i].lock, RT_WAITING_FOREVER);
  rt_memheap_free(rmem);
  /* Exit critical zone */
  rt_mutex_release(&aic_memheaps[i].lock);
}
