+hal_status_e hal_audio_receive_dmic_dma(hal_audio_handle_t *haudio,
+                                        uint8_t *pdata, uint32_t size,
+                                        uint32_t period_len) {
+  hal_status_e ret = HAL_OK;
+  uint32_t frame_bytes;
+
+  ASSERT_PARAM(haudio);
+  ASSERT_PARAM(haudio->regbase != 0);
+
+  if ((!haudio) || (!pdata) || (size == 0) || (period_len == 0) ||
+      (haudio->rxdma == NULL)) {
+    return HAL_ERROR;
+  }
+
+  if (haudio->init.samplebits != AUDIO_SAMPLEBITS_16BIT) {
+    haudio->errcode = AUDIO_ERROR_INVALID_PARAM;
+    return HAL_ERROR;
+  }
+
+  if (haudio->init.channel == AUDIO_CHANNEL_MONO) {
+    frame_bytes = 2;
+  } else if (haudio->init.channel == AUDIO_CHANNEL_STEREO) {
+    frame_bytes = 4;
+  } else {
+    haudio->errcode = AUDIO_ERROR_INVALID_PARAM;
+    return HAL_ERROR;
+  }
+
+  if ((period_len % frame_bytes) != 0 || (size % period_len) != 0) {
+    haudio->errcode = AUDIO_ERROR_INVALID_PARAM;
+    return HAL_ERROR;
+  }
+
+  if (haudio->state != AUDIO_STATE_READY) {
+    return HAL_BUSY;
+  }
+
+  HAL_LOCK(haudio);
+
+  haudio->state = AUDIO_STATE_BUSY_RX;
+  haudio->errcode = AUDIO_ERROR_NONE;
+  haudio->prxbuffer = pdata;
+  haudio->rx_xfer_size = size;
+  haudio->rx_xfer_count = size;
