    75	/**
    76	 * @brief Initialize the DMA channel with specified parameters
    77	 *
    78	 * This function initializes a DMA channel according to the parameters specified
    79	 * in the handle structure. It configures the DMA hardware, and prepares the
    80	 * channel for data transfer operations.
    81	 *
    82	 * @param hdma Pointer to the DMA handle structure containing initialization
    83	 * parameters
    84	 *
    85	 * @return HAL_OK if initialization is successful, HAL_ERROR otherwise
    86	 *
    87	 * @note Before calling this function, hal_dma_handle_init() should be called to
    88	 * initialize the handle with default parameters, and the parameters should be
    89	 * customized as needed. Also, init_cb callback should be provided to configure
    90	 * clock enable and other settings.
    91	 */
    92	hal_status_e hal_dma_init(hal_dma_handle_t *hdma) {
    93	
    94	  uint32_t ch, delta, task_cnt, val;
    95	
    96	  if (!hdma) {
    97	    return HAL_ERROR;
    98	  }
    99	
   100	  ASSERT_PARAM(0 != (hdma->init.flag & HAL_HANDLE_ALL_INIT_FLAG));
   101	  ASSERT_PARAM(hdma->regbase != 0);
   102	
   103	  if (!hdma->work_buffer || !hdma->work_buffer_len) {
   104	    hdma->errcode = DMA_ERROR_PARAM;
   105	    return HAL_ERROR;
   106	  }
   107	
   108	  /* Calculate the number of available task descriptors in work buffer */
   109	  delta = CACHE_LINE_SIZE - (((uint32_t)hdma->work_buffer) & CACHE_ADDR_MASK);
   110	  task_cnt = (hdma->work_buffer_len - delta) / sizeof(hal_dma_task_desc_t);
   111	
   112	  /* Validate work buffer size according to work mode requirements */
   113	  if (hdma->work_mode == DMA_WORK_MODE_CYCLIC) {
   114	    if (!hdma->cyclic_period_len) {
   115	      hdma->errcode = DMA_ERROR_XFER_LEN;
   116	      return HAL_ERROR;
   117	    }
   118	
   119	    if (task_cnt < 2) {
   120	      /* DMA_WORK_MODE_CYCLIC at least 2 tasks */
   121	      hdma->errcode = DMA_ERROR_PARAM;
   122	      return HAL_ERROR;
   123	    }
   124	  } else if (task_cnt < 1) {
   125	    hdma->errcode = DMA_ERROR_PARAM;
   126	    return HAL_ERROR;
   127	  }
   128	
   129	  /* Source and Sink device ID should match direction */
   130	  if (hdma->init.direction == DMA_MEMORY_TO_MEMORY) {
   131	    if (hdma->init.src_dev != hdma->init.snk_dev) {
   132	      hdma->errcode = DMA_ERROR_PARAM;
   133	      return HAL_ERROR;
   134	    }
   135	  } else if (hdma->init.direction == DMA_MEMORY_TO_DEVICE) {
   136	    if (hdma->init.src_dev != 0 || hdma->init.snk_dev == 0) {
   137	      hdma->errcode = DMA_ERROR_PARAM;
   138	      return HAL_ERROR;
   139	    }
   140	  } else if (hdma->init.direction == DMA_DEVICE_TO_MEMORY) {
   141	    if (hdma->init.src_dev == 0 || hdma->init.snk_dev != 0) {
   142	      hdma->errcode = DMA_ERROR_PARAM;
   143	      return HAL_ERROR;
   144	    }
   145	  }
   146	
   147	  hdma->state = DMA_STATE_RESET;
   148	  /* Before configure the DMA, need to enable it */
   149	  if (hdma->init_cb) {
   150	    hdma->init_cb(hdma);
   151	  }
   152	
   153	  /* Validate channel ID */
   154	  if (hdma->init.channel_id >= DMA_MAX_CHANNEL_NUM) {
   155	    hdma->errcode = DMA_ERROR_CHAN_NO_EXIST;
   156	    return HAL_ERROR;
   157	  }
   158	  ch = hdma->init.channel_id;
   159	
   160	  /* Ensure DMA channel is stopped */
   161	  writel(0, DMA_CH_EN_REG(hdma, ch));
   162	  writel(0, DMA_CH_PAUSE_REG(hdma, ch));
   163	  writel(DMA_MEM_CFG_AHB_BURST_SEL, DMA_MEM_CFG_REG(hdma));
   164	
   165	  /* Clear channel's irq enable bits */
   166	  val = readl(DMA_IRQ_EN_REG(hdma));
   167	  val &= ~DMA_IRQ_EN_CH_MASK(ch);
   168	  writel(val, DMA_IRQ_EN_REG(hdma));
   169	
   170	  /* Clear channel's irq status bits */
   171	  val = DMA_IRQ_STA_CH_MASK(ch);
   172	  writel(val, DMA_IRQ_STA_REG(hdma));
   173	
   174	  hdma->errcode = DMA_ERROR_NONE;
   175	  hdma->state = DMA_STATE_READY;
   176	
   177	  return HAL_OK;
   178	}
