   180	/**
   181	 * @brief Deinitialize the DMA channel
   182	 * @param hdma Pointer to the DMA handle structure
   183	 * @return HAL_OK on success, HAL_ERROR on failure
   184	 *
   185	 * This function deinitializes the DMA channel instance. It stops the DMA
   186	 * channel, releases resources, and calls the deinit callback if provided.
   187	 *
   188	 * The user should perform hardware resource release actions in the deinit_cb()
   189	 * callback, such as disabling DMA clock when all channels are no longer in use.
   190	 */
   191	hal_status_e hal_dma_deinit(hal_dma_handle_t *hdma) {
   192	  uint32_t ch;
   193	
   194	  if (!hdma) {
   195	    return HAL_ERROR;
   196	  }
   197	  if ((hdma->init.flag & HAL_HANDLE_ALL_INIT_FLAG) == 0) {
   198	    return HAL_ERROR;
   199	  }
   200	  if (hdma->regbase == 0) {
   201	    return HAL_ERROR;
   202	  }
   203	
   204	  if (hdma->init.channel_id >= DMA_MAX_CHANNEL_NUM) {
   205	    hdma->errcode = DMA_ERROR_CHAN_NO_EXIST;
   206	    return HAL_ERROR;
   207	  }
   208	  ch = hdma->init.channel_id;
   209	
   210	  /* Ensure DMA Channel is stopped */
   211	  writel(1, DMA_CH_PAUSE_REG(hdma, ch));
   212	  writel(0, DMA_CH_EN_REG(hdma, ch));
   213	  writel(0, DMA_CH_PAUSE_REG(hdma, ch));
   214	
   215	  /* Release other resource, and CMU disable DMA */
   216	  if (hdma->deinit_cb) {
   217	    hdma->deinit_cb(hdma);
   218	  }
   219	
   220	  hdma->errcode = DMA_ERROR_NONE;
   221	  hdma->state = DMA_STATE_RESET;
   222	  return HAL_OK;
   223	}
