   720	/**
   721	 * @brief Poll for the completion of a DMA transfer
   722	 *
   723	 * This function polls the DMA controller status registers to check for transfer
   724	 * completion or errors. It waits for a specific type of completion event (half
   725	 * task, full task, or all tasks) within a specified timeout period.
   726	 *
   727	 * @param hdma Pointer to the DMA handle structure
   728	 * @param type Type of completion to wait for:
   729	 *             - DMA_COMPELE_TYPE_HALF_TASK: Wait for half task completion
   730	 *             - DMA_COMPELE_TYPE_FULL_TASK: Wait for full task completion
   731	 *             - DMA_COMPELE_TYPE_ALL_TASKS: Wait for all tasks completion
   732	 * @param timeout Maximum time to wait for completion in milliseconds
   733	 *
   734	 * @return HAL_OK if the expected completion event occurred
   735	 *         HAL_TIMEOUT if the operation timed out
   736	 *         HAL_ERROR if an error occurred or invalid parameters were provided
   737	 *
   738	 * @note This function should be called after starting a DMA transfer with
   739	 * hal_dma_start()
   740	 */
   741	hal_status_e hal_dma_poll_for_transfer(hal_dma_handle_t *hdma,
   742	                                       hal_dma_compele_type_e type,
   743	                                       uint32_t timeout) {
   744	  uint64_t start_ms, cur_ms;
   745	  uint32_t ch, val;
   746	
   747	  /* Check for valid handle */
   748	  if (!hdma) {
   749	    return HAL_ERROR;
   750	  }
   751	
   752	  /* Validate channel ID */
   753	  if (hdma->init.channel_id >= DMA_MAX_CHANNEL_NUM) {
   754	    hdma->errcode = DMA_ERROR_CHAN_NO_EXIST;
   755	    return HAL_ERROR;
   756	  }
   757	  ch = hdma->init.channel_id;
   758	
   759	  start_ms = hal_get_tick();
   760	
   761	  /* Poll for half task completion */
   762	  if (type == DMA_COMPELE_TYPE_HALF_TASK) {
   763	    while (1) {
   764	      val = readl(DMA_IRQ_STA_REG(hdma));
   765	
   766	      /* Check for address request error */
   767	      if (val & DMA_IRQ_STA_CH_ADDR_REQ_ERR_STA(ch)) {
   768	        hdma->state = DMA_STATE_ERROR;
   769	        hdma->errcode = DMA_ERROR_ADDRESS_REQUEST;
   770	        return HAL_ERROR;
   771	      }
   772	
   773	      /* Check for half task completion interrupt */
   774	      if (val & DMA_IRQ_STA_CH_TASK_HALF_IRQ_STA(ch))
   775	        break;
   776	
   777	      cur_ms = hal_get_tick();
   778	
   779	      /* Check for timeout */
   780	      if ((cur_ms - start_ms) > timeout) {
   781	        hdma->errcode = DMA_ERROR_TIMEOUT;
   782	        return HAL_TIMEOUT;
   783	      }
   784	    }
   785	
   786	  } else if (type == DMA_COMPELE_TYPE_FULL_TASK) {
   787	    /* Poll for full task completion */
   788	    while (1) {
   789	      val = readl(DMA_IRQ_STA_REG(hdma));
   790	
   791	      /* Check for address request error */
   792	      if (val & DMA_IRQ_STA_CH_ADDR_REQ_ERR_STA(ch)) {
   793	        hdma->state = DMA_STATE_ERROR;
   794	        hdma->errcode = DMA_ERROR_ADDRESS_REQUEST;
   795	        return HAL_ERROR;
   796	      }
   797	
   798	      /* Check for full task completion interrupt */
   799	      if (val & DMA_IRQ_STA_CH_TASK_FINISH_IRQ_STA(ch))
   800	        break;
   801	
   802	      cur_ms = hal_get_tick();
   803	
   804	      /* Check for timeout */
   805	      if ((cur_ms - start_ms) > timeout) {
   806	        hdma->errcode = DMA_ERROR_TIMEOUT;
   807	        return HAL_TIMEOUT;
   808	      }
   809	    }
   810	
   811	  } else if (type == DMA_COMPELE_TYPE_ALL_TASKS) {
   812	    /* Poll for all tasks completion */
   813	    while (1) {
   814	      val = readl(DMA_IRQ_STA_REG(hdma));
   815	
   816	      /* Check for address request error */
   817	      if (val & DMA_IRQ_STA_CH_ADDR_REQ_ERR_STA(ch)) {
   818	        hdma->state = DMA_STATE_ERROR;
   819	        hdma->errcode = DMA_ERROR_ADDRESS_REQUEST;
   820	        return HAL_ERROR;
   821	      }
   822	
   823	      /* Check for all tasks completion interrupt */
   824	      if (val & DMA_IRQ_STA_CH_ALL_FINISH_IRQ_STA(ch))
   825	        break;
   826	
   827	      cur_ms = hal_get_tick();
   828	
   829	      /* Check for timeout */
   830	      if ((cur_ms - start_ms) > timeout) {
   831	        hdma->errcode = DMA_ERROR_TIMEOUT;
   832	        return HAL_TIMEOUT;
   833	      }
   834	    }
   835	
   836	    hdma->state = DMA_STATE_READY;
   837	  } else {
   838	    /* Invalid completion type */
   839	    hdma->errcode = DMA_ERROR_PARAM;
   840	    return HAL_ERROR;
   841	  }
   842	
   843	  return HAL_OK;
