   494	static int dmic_capture_wait(struct dmic_runtime *rt,
   495	                             const struct dmic_options *opts,
   496	                             uint32_t target_periods) {
   497	  uint32_t done[DMIC_BUFFER_PERIODS] = {0};
   498	  uint32_t period_events = 0;
   499	  uint32_t idle_us = 0;
   500	
   501	  while ((target_periods == 0 || period_events < target_periods) &&
   502	         !g_dmic_stop) {
   503	    bool progressed = false;
   504	
   505	    for (unsigned int slot = 0; slot < DMIC_BUFFER_PERIODS; slot++) {
   506	      uint32_t ready = rt->ready[slot];
   507	      uint32_t delta = ready - done[slot];
   508	
   509	      if (delta == 0) {
   510	        continue;
   511	      }
   512	
   513	      if (delta > 1) {
   514	        uint32_t skipped = delta - 1;
   515	        rt->lost_periods += skipped;
   516	        period_events += skipped;
   517	        done[slot] = ready - 1;
   518	      }
   519	
   520	      if (target_periods != 0 && period_events >= target_periods) {
   521	        break;
   522	      }
   523	
   524	      if (dmic_handle_period(rt, opts, slot) < 0) {
   525	        return -EIO;
   526	      }
   527	
   528	      done[slot] = ready;
   529	      period_events++;
   530	      progressed = true;
   531	    }
   532	
   533	    if (progressed) {
   534	      idle_us = 0;
   535	      continue;
   536	    }
   537	
   538	    usleep(DMIC_POLL_US);
   539	    idle_us += DMIC_POLL_US;
   540	    if (idle_us >= DMIC_NO_DATA_TIMEOUT_US) {
   541	      fprintf(stderr, "dmic: timeout waiting for DMA period interrupt\n");
   542	      return -ETIMEDOUT;
   543	    }
   544	  }
   545	
   546	  return 0;
   547	}
