    72	  val &= ~TX_MIXER_CTL_MIXER0_PATH_MASK;
    73	  val |= TX_MIXER_CTL_MIXER0_AUDOUTL_SEL | TX_MIXER_CTL_MIXER1_AUDOUTR_SEL;
    74	  writel(val, TX_MIXER_CTL_REG(haudio));
    75	  /* Configure PWM0 single output */
    76	  val = readl(TX_PWM_CTL_REG(haudio));
    77	  val &= ~TX_PWM_CTL_PWM0_MODE_MASK;
    78	  val |= TX_PWM_CTL_PWM0_EN | TX_PWM_CTL_PWM0_FADE_EN;
