    86	/**
    87	 * @brief Configures AUDIO for PWM1 single output mode.
    88	 *
    89	 *        This function sets up the audio hardware to use PWM1 as the single
    90	 * output channel. It enables the necessary digital volume control, interface,
    91	 * and sigma-delta modulator components, configures the mixer path, and sets
    92	 * PWM1 to single output mode.
    93	 *
    94	 * @param[in,out] haudio Pointer to AUDIO handle structure
    95	 *
    96	 * @note This function is internally used by the audio driver and should not be
    97	 * called directly. It assumes that the AUDIO handle has been properly
    98	 * initialized.
    99	 *
   100	 * @warning Do not call this function from an interrupt context.
   101	 */
   102	static void audio_set_pwm1(hal_audio_handle_t *haudio) {
   103	  uint32_t val;
   104	
   105	  if (!haudio)
   106	    return;
   107	  /* Enable DVC4 */
   108	  val = readl(TX_DVC3_4_CTL_REG(haudio));
   109	  val &= ~TX_DVC3_4_CTL_DVC4_MASK;
   110	  val |= TX_DVC3_4_CTL_DVC4_EN;
   111	  writel(val, TX_DVC3_4_CTL_REG(haudio));
   112	  /* Enable IF */
   113	  val = readl(TX_PLAYBACK_CTL_REG(haudio));
   114	  val &= ~TX_PLAYBACK_CTL_IF_CH0_MASK;
   115	  val &= ~TX_PLAYBACK_CTL_IF_CH1_MASK;
   116	  val |= TX_PLAYBACK_CTL_PLAYBACK_IF_EN | TX_PLAYBACK_CTL_IF_CH0_EN |
   117	         TX_PLAYBACK_CTL_IF_CH1_EN;
   118	  writel(val, TX_PLAYBACK_CTL_REG(haudio));
   119	  /* Enable SDM1 */
   120	  val = readl(TX_SDM_CTL_REG(haudio));
   121	  val &= ~TX_SDM_CTL_TX_CH1_SDM_EN_MASK;
   122	  val |= TX_SDM_CTL_TX_CH1_SDM_EN;
   123	  writel(val, TX_SDM_CTL_REG(haudio));
   124	  /* Configure MIXER audio path */
   125	  val = readl(TX_MIXER_CTL_REG(haudio));
   126	  val &= ~TX_MIXER_CTL_MIXER1_PATH_MASK;
   127	  val |= TX_MIXER_CTL_MIXER0_AUDOUTR_SEL | TX_MIXER_CTL_MIXER1_AUDOUTL_SEL;
   128	  writel(val, TX_MIXER_CTL_REG(haudio));
   129	  /* Configure PWM1 single output */
   130	  val = readl(TX_PWM_CTL_REG(haudio));
   131	  val &= ~TX_PWM_CTL_PWM1_MODE_MASK;
   132	  val |= TX_PWM_CTL_PWM1_EN | TX_PWM_CTL_PWM1_FADE_EN;
   133	  /* Check output mode */
   134	  if (haudio->init.out_mode == AUDIO_OUTPUT_MODE_PDM)
   135	    val |= TX_PWM_CTL_PWM1_MODE_PDM;
   136	
   137	  writel(val, TX_PWM_CTL_REG(haudio));
   138	}
