   140	/**
   141	 * @brief Configures AUDIO output channels based on initialization parameters.
   142	 *
   143	 *        This function selects and configures the appropriate output channels
   144	 *        according to the output_chan parameter in the AUDIO initialization
   145	 * structure. It supports various configurations including single channel, dual
   146	 * channel, and differential outputs.
   147	 *
   148	 * @param[in,out] haudio Pointer to AUDIO handle structure
   149	 *
   150	 * @note This function is internally used by the audio driver and should not be
   151	 * called directly. It assumes that the AUDIO handle has been properly
   152	 * initialized.
   153	 *
   154	 * @warning Do not call this function from an interrupt context.
   155	 */
   156	static void audio_set_channel(hal_audio_handle_t *haudio) {
   157	  uint32_t val;
   158	
   159	  if (!haudio)
   160	    return;
   161	  /* Set PWM channel */
   162	  switch (haudio->init.output_chan) {
   163	  case AUDIO_OUTPUT_CHAN_PWM1:
   164	    audio_set_pwm1(haudio);
   165	    break;
   166	  case AUDIO_OUTPUT_CHAN_PWM0_PWM1:
   167	    audio_set_pwm0(haudio);
   168	    audio_set_pwm1(haudio);
   169	    break;
   170	  case AUDIO_OUTPUT_CHAN_PWM0_DIFF:
   171	    audio_set_pwm0(haudio);
   172	    audio_set_pwm1(haudio);
   173	    val = readl(TX_PWM_CTL_REG(haudio));
   174	    val &= ~(TX_PWM_CTL_PWM0_MODE_MASK | TX_PWM_CTL_PWM1_MODE_MASK);
   175	    val |= TX_PWM_CTL_PWM0_EN | TX_PWM_CTL_PWM0_DIF_EN;
   176	    writel(val, TX_PWM_CTL_REG(haudio));
   177	    break;
   178	  case AUDIO_OUTPUT_CHAN_PWM1_DIFF:
   179	    audio_set_pwm0(haudio);
   180	    audio_set_pwm1(haudio);
   181	    val = readl(TX_PWM_CTL_REG(haudio));
   182	    val &= ~(TX_PWM_CTL_PWM0_MODE_MASK | TX_PWM_CTL_PWM1_MODE_MASK);
   183	    val |= TX_PWM_CTL_PWM1_EN | TX_PWM_CTL_PWM1_DIF_EN;
   184	    writel(val, TX_PWM_CTL_REG(haudio));
   185	    break;
   186	  case AUDIO_OUTPUT_CHAN_PWM0:
   187	  default:
   188	    audio_set_pwm0(haudio);
   189	    break;
   190	  }
   191	}
