   260	  }
   760	 * @param[in]     size    Number of units to transmit
   761	 * @param[in]     timeout Maximum time to wait for transmission completion (in
   762	 * milliseconds)
   763	 *
   764	 * @return HAL_OK on successful transmission, HAL_ERROR if parameters are
   765	 * invalid, HAL_TIMEOUT if transmission times out, HAL_BUSY if AUDIO is busy
   766	 *
   767	 * @note This is a blocking function that waits until all data is transmitted or
   768	 * timeout occurs. For non-blocking operation, consider using interrupt-based or
   769	 * DMA-based transmission.
   770	 *
   771	 * @warning Do not call this function from an interrupt context as it uses
   772	 * polling mechanism.
   773	 */
   774	hal_status_e hal_audio_transmit(hal_audio_handle_t *haudio,
   775	                                const uint8_t *pdata, uint32_t size,
   776	                                uint32_t timeout) {
   777	  uint64_t time_start;
   778	  uint32_t val, temp;
   779	  uint32_t frame_bytes;
   780	  ASSERT_PARAM(haudio);
   781	  ASSERT_PARAM(haudio->regbase != 0);
   782	
   783	  if ((!pdata) || (size == 0))
   784	    return HAL_ERROR;
   785	
   786	  if (haudio->state != AUDIO_STATE_READY)
   787	    return HAL_BUSY;
   788	
   789	  HAL_LOCK(haudio);
   790	  /* Init tickstart for timeout management*/
   791	  time_start = hal_get_tick();
   792	  /* Set state and reset error code */
   793	  haudio->state = AUDIO_STATE_BUSY_TX;
   794	  haudio->errcode = AUDIO_ERROR_NONE;
   795	  haudio->ptxbuffer = pdata;
   796	  haudio->tx_xfer_size = size;
   797	  haudio->tx_xfer_count = size;
   798	
   799	  /* Clean TX counter */
   800	  writel(0, TX_CNT_REG(haudio));
   801	  /* Enable TX GLBEN */
   802	  val = readl(GLOBE_CTL_REG(haudio));
   803	  if ((val & GLOBE_CTL_TX_GLBEN) == 0) {
   804	    val |= GLOBE_CTL_TX_GLBEN;
   805	    writel(val, GLOBE_CTL_REG(haudio));
   806	  }
   807	
   808	  frame_bytes = haudio->init.channel == AUDIO_CHANNEL_MONO ? 2 : 4;
   809	  if ((size % frame_bytes) != 0) {
   810	    haudio->errcode = AUDIO_ERROR_INVALID_PARAM;
   811	    haudio->state = AUDIO_STATE_READY;
   812	    HAL_UNLOCK(haudio);
   813	    return HAL_ERROR;
   814	  }
   815	  haudio->tx_xfer_count = size / frame_bytes;
   816	
   817	  while (haudio->tx_xfer_count > 0) {
   818	    /* Init temp first */
   819	    temp = 0;
   820	    /* Timeout check */
   821	    if ((hal_get_tick() - time_start) > timeout) {
   822	      haudio->errcode = AUDIO_ERROR_TIMEOUT;
   823	      haudio->state = AUDIO_STATE_READY;
   824	      HAL_UNLOCK(haudio);
   825	      return HAL_TIMEOUT;
   826	    }
   827	    /* Check FIFO status */
   828	    val = ((readl(FIFO_STA_REG(haudio)) >> 16) & 0xff);
   829	    if (val == 0)
   830	      continue;
   831	    /* Audio channel check */
   832	    if (haudio->init.channel == AUDIO_CHANNEL_MONO) {
   833	      temp = (uint32_t)(*haudio->ptxbuffer);
   834	      haudio->ptxbuffer++;
   835	      temp |= ((uint32_t)(*haudio->ptxbuffer) << 8);
   836	      haudio->ptxbuffer++;
   837	      /* Write 16bit data to TX FIFO */
   838	      writel(temp, TXFIFO_DATA_REG(haudio));
   839	    } else {
   840	      temp = (uint32_t)(*haudio->ptxbuffer);
   841	      haudio->ptxbuffer++;
   842	      temp |= ((uint32_t)(*haudio->ptxbuffer) << 8);
   843	      haudio->ptxbuffer++;
   844	      temp |= ((uint32_t)(*haudio->ptxbuffer) << 16);
   845	      haudio->ptxbuffer++;
   846	      temp |= ((uint32_t)(*haudio->ptxbuffer) << 24);
   847	      haudio->ptxbuffer++;
   848	      /* Write 32bit data to TX FIFO */
   849	      writel(temp, TXFIFO_DATA_REG(haudio));
   850	    }
   851	    haudio->tx_xfer_count--;
   852	  }
   853	
   854	  haudio->state = AUDIO_STATE_READY;
   855	  haudio->errcode = AUDIO_ERROR_NONE;
   856	  HAL_UNLOCK(haudio);
   857	
   858	  return HAL_OK;
   859	}
