   893	  HAL_LOCK(haudio);
   894	  /* Set state and reset error code */
   895	  haudio->state = AUDIO_STATE_BUSY_TX;
   896	  haudio->errcode = AUDIO_ERROR_NONE;
   897	  haudio->ptxbuffer = pdata;
   898	  haudio->tx_xfer_size = size;
   899	  haudio->tx_xfer_count = size;
