   926	/**
   927	 * @brief Transmits audio data through AUDIO interface using DMA mode.
   928	 *
   929	 *        This function initiates transmission of audio data through the AUDIO
   930	 * transmitter using DMA operation. It returns immediately after setting up the
   931	 * transfer.
   932	 *
   933	 * @param[in,out] haudio Pointer to AUDIO handle structure
   934	 * @param[in]     pdata  Pointer to buffer containing data to transmit
   935	 * @param[in]     size   Number of units to transmit
   936	 *
   937	 * @return HAL_OK on successful initiation, HAL_ERROR if parameters are invalid,
   938	 *         HAL_BUSY if AUDIO is busy, HAL_TIMEOUT if FIFO setup times out
   939	 *
   940	 * @note This is a non-blocking function that returns immediately.
   941	 *       Completion is indicated by the tx_dma_cb callback.
   942	 *       The function waits until FIFO is not empty to ensure DMA starts
   943	 * correctly.
   944	 *
   945	 * @warning Do not call this function from an interrupt context.
   946	 */
   947	hal_status_e hal_audio_transmit_dma(hal_audio_handle_t *haudio,
   948	                                    const uint8_t *pdata, uint32_t size) {
   949	  hal_status_e ret = HAL_OK;
   950	  uint32_t val;
   951	
   952	  ASSERT_PARAM(haudio);
   953	  ASSERT_PARAM(haudio->regbase != 0);
   954	
   955	  if ((!pdata) || (size == 0))
   956	    return HAL_ERROR;
   957	
   958	  /* Clean TX counter */
   959	  writel(0x0, TX_CNT_REG(haudio));
   960	
   961	  if (haudio->state == AUDIO_STATE_READY) {
   962	    HAL_LOCK(haudio);
   963	
   964	    haudio->state = AUDIO_STATE_BUSY_TX;
   965	    haudio->errcode = AUDIO_ERROR_NONE;
   966	    haudio->ptxbuffer = pdata;
   967	    haudio->tx_xfer_size = size;
   968	    haudio->tx_xfer_count = size;
   969	    /* Set the DMA Tx abort callback */
   970	    haudio->txdma->xfer_abort_cb = NULL;
   971	
   972	    ret = hal_dma_registger_callback(haudio->txdma,
   973	                     DMA_CB_XFER_HALF_TASK_COMPLETE_CB,
   974	                     NULL);
   975	    if (ret != HAL_OK) {
   976	      haudio->state = AUDIO_STATE_ERROR;
   977	      haudio->errcode = AUDIO_ERROR_DMA;
   978	      HAL_UNLOCK(haudio);
   979	      return ret;
   980	    }
   981	
   982	    ret = hal_dma_registger_callback(haudio->txdma,
   983	                                     DMA_CB_XFER_FULL_TASK_COMPLETE_CB,
   984	                                     NULL);
   985	    if (ret != HAL_OK) {
   986	      haudio->state = AUDIO_STATE_ERROR;
   987	      haudio->errcode = AUDIO_ERROR_DMA;
   988	      HAL_UNLOCK(haudio);
   989	      return ret;
   990	    }
   991	
   992	    ret = hal_dma_registger_callback(haudio->txdma,
   993	                                     DMA_CB_XFER_ALL_TASKS_COMPLETE_CB,
   994	                                     audio_dma_full_task_callback);
   995	    if (ret != HAL_OK) {
   996	      haudio->state = AUDIO_STATE_ERROR;
   997	      haudio->errcode = AUDIO_ERROR_DMA;
   998	      HAL_UNLOCK(haudio);
   999	      return ret;
  1000	    }
  1001	    /* Enable the Tx DMA Stream */
  1002	    ret = hal_dma_start_it(haudio->txdma, (uint32_t)haudio->ptxbuffer,
  1003	                           TXFIFO_DATA_REG(haudio), size);
  1004	    if (ret != HAL_OK) {
  1005	      auderr("Failed to start AUDIO DMA transmission");
  1006	      haudio->state = AUDIO_STATE_ERROR;
  1007	      haudio->errcode = AUDIO_ERROR_DMA;
  1008	      HAL_UNLOCK(haudio);
  1009	      return ret;
  1010	    }
  1011	    /* Enable Audio Tx DMA request */
  1012	    val = readl(FIFO_INT_EN_REG(haudio));
  1013	    val |= FIFO_INT_EN_AUDOUT_DRQ_EN;
  1014	    writel(val, FIFO_INT_EN_REG(haudio));
  1015	    /* Check if the Audio is already enabled */
  1016	    val = readl(GLOBE_CTL_REG(haudio));
  1017	    if ((val & GLOBE_CTL_TX_GLBEN) == 0) {
  1018	      val |= GLOBE_CTL_TX_GLBEN;
  1019	      writel(val, GLOBE_CTL_REG(haudio));
  1020	    }
  1021	    HAL_UNLOCK(haudio);
  1022	
  1023	    return HAL_OK;
  1024	  } else {
  1025	    auderr("AUDIO is busy, cannot start DMA transmission");
  1026	    return HAL_BUSY;
  1027	  }
  1028	}
