  1030	hal_status_e hal_audio_receive_dmic_dma(hal_audio_handle_t *haudio,
  1031	                                        uint8_t *pdata, uint32_t size,
  1032	                                        uint32_t period_len) {
  1033	  hal_status_e ret = HAL_OK;
  1034	  uint32_t frame_bytes;
  1035	
  1036	  ASSERT_PARAM(haudio);
  1037	  ASSERT_PARAM(haudio->regbase != 0);
  1038	
  1039	  if ((!haudio) || (!pdata) || (size == 0) || (period_len == 0) ||
  1040	      (haudio->rxdma == NULL)) {
  1041	    return HAL_ERROR;
  1042	  }
  1043	
  1044	  if (haudio->init.samplebits != AUDIO_SAMPLEBITS_16BIT) {
  1045	    haudio->errcode = AUDIO_ERROR_INVALID_PARAM;
  1046	    return HAL_ERROR;
  1047	  }
  1048	
