   307	    reg_val |= RX_DMIC_IF_DEC1_FLT | RX_DMIC_IF_DEC2_FLT | RX_DMIC_IF_EN;
   308	    writel(reg_val, RX_DMIC_IF_CTRL_REG(haudio));
   309	
   310	    reg_val = readl(RX_DVC_1_2_CTRL_REG(haudio));
   311	    reg_val |= RX_DVC_MASK;
   312	    writel(reg_val, RX_DVC_1_2_CTRL_REG(haudio));
   313	
   314	    reg_val = readl(DMIC_RXFIFO_CTRL_REG(haudio));
   315	    reg_val |= DMIC_RXFIFO_CTRL_RX_FIFO_CH_MASK;
   316	    writel(reg_val, DMIC_RXFIFO_CTRL_REG(haudio));
   317	  }
   318	}
