   471	/**
   472	 * @brief Initializes the AUDIO peripheral with specified parameters.
   473	 *
   474	 *        This function fully initializes the AUDIO peripheral according to the
   475	 * parameters specified in the AUDIO handle structure. It configures all
   476	 * hardware registers, sets up the audio path, and prepares the peripheral for
   477	 * data transmission.
   478	 *
   479	 * @param[in,out] haudio Pointer to AUDIO handle structure containing
   480	 * initialization parameters
   481	 *
   482	 * @return HAL_OK on successful initialization, HAL_ERROR if parameters are
   483	 * invalid, HAL_BUSY if AUDIO is busy
   484	 *
   485	 * @note This function requires that the init_cb callback is registered to
   486	 * configure clocks. The samplebits, samplerate, and channel parameters must be
   487	 * set by the application.
   488	 *
   489	 * @warning Do not call this function from an interrupt context.
   490	 */
   491	hal_status_e hal_audio_init(hal_audio_handle_t *haudio) {
   492	  uint32_t val, fade_val;
   493	  uint16_t target_vol;
   494	
   495	  if (!haudio)
   496	    return HAL_ERROR;
   497	
   498	  ASSERT_PARAM(0 != (haudio->init.flag & HAL_HANDLE_ALL_INIT_FLAG));
   499	  ASSERT_PARAM(haudio->regbase != 0);
   500	
   501	  HAL_LOCK(haudio);
   502	  if (haudio->init_cb)
   503	    /* Should set input frequency and enable clock for AUDIO in callback */
   504	    haudio->init_cb(haudio);
   505	  else {
   506	    hal_audio_clock_init();
   507	  }
   508	  /* Set audio volume */
   509	  if (haudio->init.target_volume != ADUIO_DEFAULT_TAR_VOLUME) {
   510	    target_vol = ADUIO_DEFAULT_TAR_VOLUME - haudio->init.target_volume;
   511	    if (target_vol == 100)
   512	      fade_val = 0;
   513	    else
   514	      fade_val = AUDIO_DEFAULT_FADE_VOL - (target_vol * AUDIO_DEFAULT_FADE_MAP);
   515	    val = readl(FADE_CTL1_REG(haudio));
   516	    val &= ~FADE_CTL1_TARGET_VOL_MASK;
   517	    val |= fade_val;
   518	    writel(val, FADE_CTL1_REG(haudio));
   519	  }
   520	  /* Set fade step */
   521	  if (haudio->init.fade_step != AUDIO_DEFAULT_FADE_STEP) {
   522	    val = readl(FADE_CTL0_REG(haudio));
   523	    val &= ~FADE_CTL0_FADE_STEP_MASK;
   524	    val |= haudio->init.fade_step;
   525	    writel(val, FADE_CTL0_REG(haudio));
   526	  }
   527	  /* Set fade speed */
   528	  if (haudio->init.fade_speed != AUDIO_DEFAULT_FADE_SPEED) {
   529	    val = readl(FADE_CTL0_REG(haudio));
   530	    val &= ~FADE_CTL0_FADE_SPEED_MASK;
   531	    val |= haudio->init.fade_speed;
   532	    writel(val, FADE_CTL0_REG(haudio));
   533	  }
   534	  /* Set DVC gain */
   535	  if (haudio->init.dvc_volume != AUDIO_DEFAULT_DVC_VOLUME) {
   536	    val = readl(TX_DVC3_4_CTL_REG(haudio));
   537	    val &= ~TX_DVC3_4_CTL_DVC3_GAIN_MASK;
   538	    val &= ~TX_DVC3_4_CTL_DVC4_GAIN_MASK;
   539	    val |= (haudio->init.dvc_volume << TX_DVC3_4_CTL_DVC3_GAIN_SHIFT |
   540	            haudio->init.dvc_volume << TX_DVC3_4_CTL_DVC4_GAIN_SHIFT);
   541	    writel(val, TX_DVC3_4_CTL_REG(haudio));
   542	  }
   543	  /* Set filter shift */
   544	  if (haudio->init.fltout_shift != AUDIO_FLTOUT_SHIFT_13BIT) {
   545	    val = readl(TX_PLAYBACK_CTL_REG(haudio));
   546	    val &= ~TX_PLAYBACK_CTL_FLTOUT_SHIFTN_MASK;
   547	    val |= haudio->init.fltout_shift << TX_PLAYBACK_CTL_FLTOUT_SHIFTN_SHIFT;
   548	    writel(val, TX_PLAYBACK_CTL_REG(haudio));
   549	  }
   550	  /* Set output and check output mode */
   551	  audio_set_channel(haudio);
   552	  /* Set SDM gain */
   553	  if (haudio->init.sdm_gain != AUDIO_SDM_GAIN_1) {
   554	    val = readl(TX_SDM_CTL_REG(haudio));
   555	    val &= ~(TX_SDM_CTL_TX_CH0_SDM_GAIN_A0_MASK |
   556	             TX_SDM_CTL_TX_CH0_SDM_GAIN_B0_MASK |
   557	             TX_SDM_CTL_TX_CH0_SDM_GAIN_C0_MASK |
   558	             TX_SDM_CTL_TX_CH1_SDM_GAIN_A0_MASK |
   559	             TX_SDM_CTL_TX_CH1_SDM_GAIN_B0_MASK |
   560	             TX_SDM_CTL_TX_CH1_SDM_GAIN_C0_MASK);
   561	    val |= (haudio->init.sdm_gain << TX_SDM_CTL_TX_CH0_SDM_GAIN_A0_SHIFT |
   562	            haudio->init.sdm_gain << TX_SDM_CTL_TX_CH0_SDM_GAIN_B0_SHIFT |
   563	            haudio->init.sdm_gain << TX_SDM_CTL_TX_CH0_SDM_GAIN_C0_SHIFT |
   564	            haudio->init.sdm_gain << TX_SDM_CTL_TX_CH1_SDM_GAIN_A0_SHIFT |
   565	            haudio->init.sdm_gain << TX_SDM_CTL_TX_CH1_SDM_GAIN_B0_SHIFT |
   566	            haudio->init.sdm_gain << TX_SDM_CTL_TX_CH1_SDM_GAIN_C0_SHIFT);
   567	    writel(val, TX_SDM_CTL_REG(haudio));
   568	  }
   569	  /* Check samplebits */
   570	  if (haudio->init.samplebits != AUDIO_SAMPLEBITS_16BIT) {
   571	    haudio->errcode = AUDIO_ERROR_INVALID_PARAM;
   572	    return HAL_ERROR;
   573	  }
   574	  /* Set samplerate */
   575	  hal_audio_set_samplerate(haudio);
   576	  /* Set output channel num */
   577	  val = readl(TXFIFO_CTL_REG(haudio));
   578	  val &= ~(TXFIFO_CTL_TX_FIFO_CH0_EN_MASK | TXFIFO_CTL_TX_FIFO_CH1_EN_MASK);
   579	  /* Maybe need to check the channel num, now is all fifo open */
   580	  val |= TXFIFO_CTL_TX_FIFO_CH0_EN | TXFIFO_CTL_TX_FIFO_CH1_EN;
   581	  writel(val, TXFIFO_CTL_REG(haudio));
   582	  /*Flush TXFIFO*/
   583	  val = readl(TXFIFO_CTL_REG(haudio));
   584	  val |= TXFIFO_CTL_TX_FIFO_FLUSH_MASK;
   585	  val = readl(TXFIFO_CTL_REG(haudio));
   586	
   587	  haudio->errcode = AUDIO_ERROR_NONE;
   588	  haudio->state = AUDIO_STATE_READY;
   589	  HAL_UNLOCK(haudio);
   590	
   591	  return HAL_OK;
   592	}
