   631	/**
   632	 * @brief AUDIO transmit interrupt service routine for 16-bit data.
   633	 *
   634	 *        This function is called when the AUDIO transmit FIFO has space
   635	 * available. It writes 16-bit audio data from the buffer to the transmit FIFO
   636	 * until completion.
   637	 *
   638	 * @param[in,out] haudio Pointer to AUDIO handle structure
   639	 *
   640	 * @note This function disables further TX interrupts after completing
   641	 * transmission. It handles mono audio data (16 bits per sample).
   642	 *
   643	 * @warning Must only be called from AUDIO interrupt context.
   644	 */
   645	static void audio_tx_isr_16bit(hal_audio_handle_t *haudio) {
   646	  uint32_t i, val, temp = 0;
   647	
   648	  if (!haudio->tx_xfer_count) {
   649	    /* Disable TX interrupt */
   650	    writel(0x0, FIFO_INT_EN_REG(haudio));
   651	    haudio->state = AUDIO_STATE_READY;
   652	    if (haudio->tx_interrupt_cb)
   653	      haudio->tx_interrupt_cb(haudio);
   654	  } else {
   655	    /* Get FIFO available space */
   656	    val = ((readl(FIFO_STA_REG(haudio)) >> 16) & 0xff);
   657	    /* Get the minimum value between FIFO available space and transfer count */
   658	    val = (val > haudio->tx_xfer_count) ? haudio->tx_xfer_count : val;
   659	    for (i = 0; i < val; i++) {
   660	      temp = 0;
   661	      temp = (uint32_t)(*haudio->ptxbuffer);
   662	      haudio->ptxbuffer++;
   663	      temp |= ((uint32_t)(*haudio->ptxbuffer) << 8);
   664	      haudio->ptxbuffer++;
   665	      /* Write 32bit data to TX FIFO */
   666	      writel(temp, TXFIFO_DATA_REG(haudio));
   667	      haudio->tx_xfer_count--;
   668	    }
   669	  }
   670	}
