   672	/**
   673	 * @brief AUDIO transmit interrupt service routine for 32-bit data.
   674	 *
   675	 *        This function is called when the AUDIO transmit FIFO has space
   676	 * available. It writes 32-bit audio data from the buffer to the transmit FIFO
   677	 * until completion.
   678	 *
   679	 * @param[in,out] haudio Pointer to AUDIO handle structure
   680	 *
   681	 * @note This function disables further TX interrupts after completing
   682	 * transmission. It handles stereo audio data (32 bits per sample).
   683	 *
   684	 * @warning Must only be called from AUDIO interrupt context.
   685	 */
   686	static void audio_tx_isr_32bit(hal_audio_handle_t *haudio) {
   687	  uint32_t i, val, temp = 0;
   688	
   689	  if (!haudio->tx_xfer_count) {
   690	    /* Disable TX interrupt */
   691	    writel(0x0, FIFO_INT_EN_REG(haudio));
   692	    haudio->state = AUDIO_STATE_READY;
   693	    if (haudio->tx_interrupt_cb)
   694	      haudio->tx_interrupt_cb(haudio);
   695	  } else {
   696	    /* Get FIFO available space */
   697	    val = ((readl(FIFO_STA_REG(haudio)) >> 16) & 0xff);
   698	    /* Get the minimum value between FIFO available space and transfer count */
   699	    val = (val > haudio->tx_xfer_count) ? haudio->tx_xfer_count : val;
   700	    for (i = 0; i < val; i++) {
   701	      temp = 0;
   702	      temp = (uint32_t)(*haudio->ptxbuffer);
   703	      haudio->ptxbuffer++;
   704	      temp |= ((uint32_t)(*haudio->ptxbuffer) << 8);
   705	      haudio->ptxbuffer++;
   706	      temp |= ((uint32_t)(*haudio->ptxbuffer) << 16);
   707	      haudio->ptxbuffer++;
   708	      temp |= ((uint32_t)(*haudio->ptxbuffer) << 24);
   709	      haudio->ptxbuffer++;
