   256	        writel(reg_val, codec->reg_base + RX_HPF_1_2_CTRL_REG);
   257	        /* Enable DF1 and DMIC interface*/
   258	        reg_val = readl(codec->reg_base + RX_DMIC_IF_CTRL_REG);
   259	        reg_val &= ~RX_DMIC_IF_DEC_EN_MASK;
   260	        reg_val |= RX_DMIC_IF_DEC1_FLT | RX_DMIC_IF_EN;
   261	        writel(reg_val, codec->reg_base + RX_DMIC_IF_CTRL_REG);
   262	        /* Enable DVC1 */
   263	        reg_val = readl(codec->reg_base + RX_DVC_1_2_CTRL_REG);
   264	        reg_val &= ~RX_DVC_MASK;
   265	        reg_val |= RX_DVC1_EN;
   266	        writel(reg_val, codec->reg_base + RX_DVC_1_2_CTRL_REG);
   267	        /* Enable ch0 */
   268	        reg_val = readl(codec->reg_base + DMIC_RXFIFO_CTRL_REG);
   269	        reg_val &= ~DMIC_RXFIFO_CH_MASK;
   270	        reg_val |= DMIC_RXFIFO_CH0_EN;
   271	        writel(reg_val, codec->reg_base + DMIC_RXFIFO_CTRL_REG);
   272	    }
   273	    else if (ch == 2)
   274	    {
   275	        /* Enable HPF1_2 */
   276	        reg_val = readl(codec->reg_base + RX_HPF_1_2_CTRL_REG);
   277	        reg_val &= ~RX_HPF_MASK;
   278	        reg_val |= RX_HPF1_EN | RX_HPF2_EN;
   279	        writel(reg_val, codec->reg_base + RX_HPF_1_2_CTRL_REG);
   280	        /* Enable DF1_2 and DMIC interface*/
   281	        reg_val = readl(codec->reg_base + RX_DMIC_IF_CTRL_REG);
   282	        reg_val &= ~RX_DMIC_IF_DEC_EN_MASK;
   283	        reg_val |= RX_DMIC_IF_DEC1_FLT | RX_DMIC_IF_DEC2_FLT | RX_DMIC_IF_EN;
   284	        writel(reg_val, codec->reg_base + RX_DMIC_IF_CTRL_REG);
   285	        /* Enable DVC1 DVC2 */
   286	        reg_val = readl(codec->reg_base + RX_DVC_1_2_CTRL_REG);
   287	        reg_val |= RX_DVC_MASK;
   288	        writel(reg_val, codec->reg_base + RX_DVC_1_2_CTRL_REG);
   289	        /* Enable ch0 ch1 */
   290	        reg_val = readl(codec->reg_base + DMIC_RXFIFO_CTRL_REG);
   291	        reg_val |= DMIC_RXFIFO_CH_MASK;
   292	        writel(reg_val, codec->reg_base + DMIC_RXFIFO_CTRL_REG);
   293	    }
   294	}
