   296	void hal_audio_set_amic_channel(aic_audio_ctrl *codec)
   297	{
   298	    uint32_t reg_val;
   299	
   300	    /* Enable HPF0 */
   301	    reg_val = readl(codec->reg_base + ADC_HPF0_CTRL_REG);
   302	    reg_val |= ADC_HPF0_CTRL_HPF0_EN;
   303	    writel(reg_val, codec->reg_base + ADC_HPF0_CTRL_REG);
   304	    /* Enable MBIAS PGA ADC */
   305	    reg_val = readl(codec->reg_base + ADC_CTL1_REG);
   306	    reg_val |= ADC_CTL1_ADC_EN | ADC_CTL1_PGA_EN | ADC_CTL1_MBIAS_EN;
   307	    writel(reg_val, codec->reg_base + ADC_CTL1_REG);
   308	    /* Enable DF0 */
   309	    reg_val = readl(codec->reg_base + ADC_IF_CTRL_REG);
   310	    reg_val |= ADC_IF_CTRL_EN_DEC0_MASK;
   311	    writel(reg_val, codec->reg_base + ADC_IF_CTRL_REG);
   312	    /* Enable DVC0 */
   313	    reg_val = readl(codec->reg_base + ADC_DVC0_CTRL_REG);
   314	    reg_val |= ADC_DVC0_CTRL_DVC0_EN;
   315	    writel(reg_val, codec->reg_base + ADC_DVC0_CTRL_REG);
   316	    /* Enable amic channel */
   317	    reg_val = readl(codec->reg_base + ADC_RXFIFO_CTRL_REG);
   318	    reg_val |= ADC_RXFIFO_EN;
   319	    writel(reg_val, codec->reg_base + ADC_RXFIFO_CTRL_REG);
   320	    /* Set PGA CTRL */
   321	    reg_val = readl(codec->reg_base + ADC_CTL2_REG);
   322	    reg_val |= ADC_CTL2_PGA_GAIN_SEL;
   323	    writel(reg_val, codec->reg_base + ADC_CTL2_REG);
   324	}
