   326	static void dma_transfer_period_callback(void *arg)
   327	{
   328	    struct aic_audio_transfer_info *info;
   329	    aic_audio_ctrl *codec;
   330	
   331	    info = (struct aic_audio_transfer_info *)arg;
   332	
   333	    if (info->transfer_type == AUDIO_TRANSFER_TYPE_TX)
   334	    {
   335	        codec = container_of(info, aic_audio_ctrl, tx_info);
   336	        if (codec->callback)
   337	            codec->callback(codec, (void *)AUDIO_TX_PERIOD_INT);
   338	    }
   339	    else if (info->transfer_type == AUDIO_TRANSFER_TYPE_DMIC)
   340	    {
   341	        codec = container_of(info, aic_audio_ctrl, dmic_info);
   342	        if (codec->callback)
   343	            codec->callback(codec, (void *)AUDIO_RX_DMIC_PERIOD_INT);
   344	    }
   345	    else if (info->transfer_type == AUDIO_TRANSFER_TYPE_AMIC)
   346	    {
   347	        codec = container_of(info, aic_audio_ctrl, amic_info);
   348	        if (codec->callback)
   349	            codec->callback(codec, (void *)AUDIO_RX_AMIC_PERIOD_INT);
   350	    }
   351	}
