   353	void hal_audio_playback_start(aic_audio_ctrl *codec)
   354	{
   355	    struct dma_slave_config config;
   356	    struct aic_audio_transfer_info *info;
   357	
   358	    config.direction = DMA_MEM_TO_DEV;
   359	    config.dst_addr = codec->reg_base + TXFIFO_DATA_REG;
   360	    config.slave_id = DMA_ID_AUDIO_DMIC;
   361	    config.src_maxburst = 1;
   362	    config.dst_maxburst = 1;
   363	
   364	    /* AudioCodec only support 16bit sample width */
   365	    if (codec->config.channel == 2)
   366	    {
   367	        config.src_addr_width = DMA_SLAVE_BUSWIDTH_UNDEFINED;
   368	        config.dst_addr_width = DMA_SLAVE_BUSWIDTH_4_BYTES;
   369	    }
   370	    else if (codec->config.channel == 1)
   371	    {
   372	        config.src_addr_width = DMA_SLAVE_BUSWIDTH_UNDEFINED;
   373	        config.dst_addr_width = DMA_SLAVE_BUSWIDTH_2_BYTES;
   374	    }
   375	
   376	    info = &codec->tx_info;
   377	
   378	    info->transfer_type = AUDIO_TRANSFER_TYPE_TX;
   379	
   380	    info->dma_chan = hal_request_dma_chan();
   381	    if (!info->dma_chan) {
   382	        hal_log_err("playback request dma channel error\n");
   383	        return;
   384	    }
   385	
   386	    hal_dma_chan_register_cb(info->dma_chan, dma_transfer_period_callback,
   387	                             (void *)info);
   388	    hal_dma_chan_config(info->dma_chan, &config);
   389	    /* Configure DMA transfer */
   390	    hal_dma_chan_prep_cyclic(info->dma_chan, (ulong)info->buf_info.buf,
   391	                             info->buf_info.buf_len, info->buf_info.period_len,
   392	                             DMA_MEM_TO_DEV);
   393	    hal_dma_chan_start(info->dma_chan);
   394	    /* Enable TX global */
   395	    hal_audio_enable_tx_global(codec);
   396	    /* Enable AUDOUT DRQ */
   397	    hal_audio_tx_enable_drq(codec);
   398	}
