    86	rt_err_t drv_dmic_configure(struct rt_audio_device *audio,
    87	                            struct rt_audio_caps *caps)
    88	{
    89	    rt_err_t ret = RT_EOK;
    90	    struct aic_dmic *p_dmic_dev;
    91	    aic_audio_ctrl *pcodec;
    92	    rt_uint32_t volume, reg_volume;
    93	
    94	    p_dmic_dev = (struct aic_dmic *)audio;
    95	    pcodec = &p_dmic_dev->codec;
    96	
    97	    switch (caps->main_type)
    98	    {
    99	    case AUDIO_TYPE_MIXER:
   100	    {
   101	        switch (caps->sub_type)
   102	        {
   103	        case AUDIO_MIXER_VOLUME:
   104	            volume = caps->udata.value;
   105	            /*
   106	             * Set max user volume to 0db
   107	             */
   108	            reg_volume = volume * MAX_VOLUME_0DB / 100;
   109	
   110	            hal_audio_set_dmic_volume(pcodec, reg_volume);
   111	            p_dmic_dev->volume = volume;
   112	            break;
   113	
   114	        default:
   115	            ret = -RT_ERROR;
   116	            break;
   117	        }
   118	
   119	        break;
   120	    }
   121	
   122	    case AUDIO_TYPE_INPUT:
   123	    {
   124	        switch (caps->sub_type)
   125	        {
   126	        case AUDIO_DSP_PARAM:
   127	            /* AudioCodec only support 16 bits */
   128	            hal_audio_set_dmic_channel(pcodec, caps->udata.config.channels);
   129	            hal_audio_set_samplerate(pcodec, caps->udata.config.samplerate);
   130	            pcodec->config.samplerate = caps->udata.config.samplerate;
   131	            pcodec->config.channel = caps->udata.config.channels;
   132	            pcodec->config.samplebits = 16;
   133	            LOG_D("set samplerate %d, channel: %d\n",
   134	                  caps->udata.config.samplerate, caps->udata.config.channels);
   135	            break;
   136	
   137	        case AUDIO_DSP_SAMPLERATE:
   138	            hal_audio_set_samplerate(pcodec, caps->udata.config.samplerate);
   139	            pcodec->config.samplerate = caps->udata.config.samplerate;
   140	            LOG_D("set samplerate %d\n", caps->udata.config.samplerate);
   141	            break;
   142	
   143	        case AUDIO_DSP_CHANNELS:
   144	            hal_audio_set_dmic_channel(pcodec, caps->udata.config.channels);
   145	            pcodec->config.channel = caps->udata.config.channels;
   146	            LOG_D("set channel: %d\n", caps->udata.config.channels);
   147	            break;
   148	
   149	        case AUDIO_DSP_SAMPLEBITS:
   150	            LOG_D("AudioCodec only support 16 sample bits\n");
   151	            break;
   152	
   153	        default:
   154	            ret = -RT_ERROR;
   155	        }
   156	
   157	        hal_audio_dmic_start(pcodec);
   158	
   159	        break;
   160	    }
   161	
   162	    default:
   163	        break;
   164	    }
   165	
   166	    return ret;
   167	}
