   424	/**
   425	 * @brief Start DMA transfer in polling mode
   426	 *
   427	 * This function starts a DMA transfer operation in polling mode. After starting
   428	 * the transfer, the user needs to call hal_dma_poll_for_transfer() to wait for
   429	 * the transfer completion.
   430	 *
   431	 * @param hdma Pointer to the DMA handle structure
   432	 * @param src Source address for the DMA transfer
   433	 * @param dst Destination address for the DMA transfer
   434	 * @param len Length of data to transfer
   435	 *
   436	 * @return HAL_OK if transfer started successfully, HAL_ERROR otherwise
   437	 *
   438	 * @note This function supports both normal and cyclic work modes. In cyclic
   439	 * mode, multiple tasks will be configured to form a circular chain.
   440	 */
   441	hal_status_e hal_dma_start(hal_dma_handle_t *hdma, uint32_t src, uint32_t dst,
   442	                           uint32_t len) {
   443	  hal_dma_task_desc_t *task;
   444	  uint32_t ch, mode, val;
   445	  hal_status_e ret;
   446	
   447	  /* Check for valid handle */
   448	  if (!hdma) {
   449	    return HAL_ERROR;
   450	  }
   451	
   452	  HAL_LOCK(hdma);
   453	
   454	  /* Validate transfer parameters */
   455	  ret = dma_xfer_param_check(hdma, src, dst, len);
   456	  if (ret != HAL_OK) {
   457	    auderr(
   458	        "DMA transfer parameter check failed: src=0x%08x dst=0x%08x len=%u\n",
   459	        src, dst, len);
   460	    goto out;
   461	  }
   462	
   463	  /* Check if DMA channel is ready */
   464	  if (hdma->state != DMA_STATE_READY) {
   465	    hdma->errcode = DMA_ERROR_BUSY;
   466	    ret = HAL_ERROR;
   467	    auderr("DMA channel is not ready, current state=%u\n", hdma->state);
   468	    goto out;
   469	  }
   470	
   471	  /* Configure task descriptor based on work mode */
   472	  if (hdma->work_mode == DMA_WORK_MODE_NORMAL) {
   473	    task = dma_normal_mode_task_cfg(hdma, src, dst, len);
   474	  } else if (hdma->work_mode == DMA_WORK_MODE_CYCLIC) {
   475	    task = dma_cyclic_mode_task_cfg(hdma, src, dst, len);
   476	    if (!task) {
   477	      auderr("Failed to configure DMA cyclic mode tasks\n");
   478	      ret = HAL_ERROR;
   479	      goto out;
   480	    }
   481	  } else {
   482	    hdma->errcode = DMA_ERROR_WORK_MODE;
   483	    ret = HAL_ERROR;
   484	    auderr("Invalid DMA work mode: %u\n", hdma->work_mode);
   485	    goto out;
   486	  }
   487	
   488	  ch = hdma->init.channel_id;
   489	
   490	  /* Configure DMA channel mode based on source/sink device modes */
   491	  mode = 0;
   492	  if (hdma->init.src_mode == DMA_MODE_HANDSHAKE) {
   493	    mode |= DMA_MODE_DMA_SRC_MODE_MASK;
   494	    if (hdma->init.src_burst != DMA_XFER_BURST_1)
   495	      mode |= DMA_MODE_HANDSHAKE_ENABLE_MASK;
   496	  }
   497	  if (hdma->init.snk_mode == DMA_MODE_HANDSHAKE) {
   498	    mode |= DMA_MODE_DMA_SNK_MODE_MASK;
   499	    if (hdma->init.snk_burst != DMA_XFER_BURST_1)
   500	      mode |= DMA_MODE_HANDSHAKE_ENABLE_MASK;
   501	  }
   502	  writel(mode, DMA_MODE_REG(hdma, ch));
   503	
   504	  /* Clear channel's irq enable bits */
   505	  val = readl(DMA_IRQ_EN_REG(hdma));
   506	  val &= ~DMA_IRQ_EN_CH_MASK(ch);
   507	  writel(val, DMA_IRQ_EN_REG(hdma));
   508	
   509	  /* Clear channel's irq status bits */
   510	  val = DMA_IRQ_STA_CH_MASK(ch);
   530	 * functions.
   531	 *
   532	 * @param hdma Pointer to the DMA handle structure
   533	 * @param src Source address for the DMA transfer
   534	 * @param dst Destination address for the DMA transfer
   535	 * @param len Length of data to transfer
   536	 *
   537	 * @return HAL_OK if transfer started successfully, HAL_ERROR otherwise
   538	 *
   539	 * @note This function supports both normal and cyclic work modes. In cyclic
   540	 * mode, multiple tasks will be configured to form a circular chain. The user
   541	 * must register appropriate callback functions to handle transfer completion
   542	 * events.
   543	 */
   544	hal_status_e hal_dma_start_it(hal_dma_handle_t *hdma, uint32_t src,
   545	                              uint32_t dst, uint32_t len) {
   546	  hal_dma_task_desc_t *task;
   547	  uint32_t ch, mode, val;
   548	  hal_status_e ret;
   549	
   550	  if (!hdma) {
   551	    return HAL_ERROR;
   552	  }
   553	
   554	  HAL_LOCK(hdma);
   555	
   556	  ret = dma_xfer_param_check(hdma, src, dst, len);
   557	  if (ret != HAL_OK) {
   558	    goto out;
   559	  }
   560	
   561	  if (hdma->state != DMA_STATE_READY) {
   562	    hdma->errcode = DMA_ERROR_BUSY;
   563	    ret = HAL_ERROR;
   564	    goto out;
   565	  }
   566	
   567	  if (hdma->work_mode == DMA_WORK_MODE_NORMAL) {
   568	    task = dma_normal_mode_task_cfg(hdma, src, dst, len);
   569	  } else if (hdma->work_mode == DMA_WORK_MODE_CYCLIC) {
   570	    task = dma_cyclic_mode_task_cfg(hdma, src, dst, len);
   571	    if (!task) {
   572	      ret = HAL_ERROR;
   573	      goto out;
   574	    }
   575	  } else {
   576	    hdma->errcode = DMA_ERROR_WORK_MODE;
   577	    ret = HAL_ERROR;
   578	    goto out;
   579	  }
   580	
   581	  ch = hdma->init.channel_id;
   582	
   583	  /* Configure DMA channel mode based on source/sink device modes */
   584	  mode = 0;
   585	  if (hdma->init.src_mode == DMA_MODE_HANDSHAKE) {
   586	    mode |= DMA_MODE_DMA_SRC_MODE_MASK;
   587	    if (hdma->init.src_burst != DMA_XFER_BURST_1)
   588	      mode |= DMA_MODE_HANDSHAKE_ENABLE_MASK;
   589	  }
   590	  if (hdma->init.snk_mode == DMA_MODE_HANDSHAKE) {
   591	    mode |= DMA_MODE_DMA_SNK_MODE_MASK;
   592	    if (hdma->init.snk_burst != DMA_XFER_BURST_1)
   593	      mode |= DMA_MODE_HANDSHAKE_ENABLE_MASK;
   594	  }
   595	  writel(mode, DMA_MODE_REG(hdma, ch));
   596	
   597	  /* Clear channel's irq status bits */
   598	  val = DMA_IRQ_STA_CH_MASK(ch);
   599	  writel(val, DMA_IRQ_STA_REG(hdma));
   600	
   601	  /* Enable channel's irq enable bits */
   602	  val = readl(DMA_IRQ_EN_REG(hdma));
   603	  val |= DMA_IRQ_EN_CH_MASK(ch);
   604	  writel(val, DMA_IRQ_EN_REG(hdma));
