   618	/**
   619	 * @brief Abort DMA transfer in polling mode
   620	 *
   621	 * This function aborts an ongoing DMA transfer by pausing and disabling
   622	 * the DMA channel.
   623	 *
   624	 * @param hdma Pointer to the DMA handle structure
   625	 *
   626	 * @return HAL_OK if abort successful, HAL_ERROR otherwise
   627	 *
   628	 * @note This function should only be called when DMA is in BUSY state
   629	 */
   630	hal_status_e hal_dma_abort(hal_dma_handle_t *hdma) {
   631	  uint32_t ch;
   632	
   633	  if (!hdma) {
   634	    return HAL_ERROR;
   635	  }
   636	
   637	  HAL_LOCK(hdma);
   638	
   639	  if (hdma->init.channel_id >= DMA_MAX_CHANNEL_NUM) {
   640	    hdma->errcode = DMA_ERROR_CHAN_NO_EXIST;
   641	    HAL_UNLOCK(hdma);
   642	    return HAL_ERROR;
   643	  }
   644	
   645	  if (hdma->state != DMA_STATE_BUSY) {
   646	    hdma->errcode = DMA_ERROR_BUSY;
