   662	/**
   663	 * @brief Abort an ongoing DMA transfer in interrupt mode
   664	 * @param hdma Pointer to a hal_dma_handle_t structure that contains
   665	 *        the configuration information for the specified DMA Channel
   666	 * @retval hal_status_e HAL status
   667	 *         - HAL_OK if the abort operation was successful
   668	 *         - HAL_ERROR if an error occurred
   669	 */
   670	hal_status_e hal_dma_abort_it(hal_dma_handle_t *hdma) {
   671	  uint32_t ch, val;
   672	
   673	  /* Check for invalid handle */
   674	  if (!hdma) {
   675	    return HAL_ERROR;
   676	  }
   677	
   678	  HAL_LOCK(hdma);
   679	
   680	  /* Validate channel ID */
   681	  if (hdma->init.channel_id >= DMA_MAX_CHANNEL_NUM) {
   682	    hdma->errcode = DMA_ERROR_CHAN_NO_EXIST;
   683	    HAL_UNLOCK(hdma);
   684	    return HAL_ERROR;
   685	  }
   686	
   687	  /* Check if DMA is busy */
   688	  if (hdma->state != DMA_STATE_BUSY) {
   689	    hdma->errcode = DMA_ERROR_BUSY;
   690	    HAL_UNLOCK(hdma);
   691	    return HAL_ERROR;
   692	  }
   693	
   694	  ch = hdma->init.channel_id;
   695	
   696	  /* Pause and disable the DMA channel */
   697	  writel(1, DMA_CH_PAUSE_REG(hdma, ch));
   698	  writel(0, DMA_CH_EN_REG(hdma, ch));
   699	
