   175	    val |= TX_PWM_CTL_PWM0_EN | TX_PWM_CTL_PWM0_DIF_EN;
   176	    writel(val, TX_PWM_CTL_REG(haudio));
   177	    break;
   178	  case AUDIO_OUTPUT_CHAN_PWM1_DIFF:
   179	    audio_set_pwm0(haudio);
   180	    audio_set_pwm1(haudio);
   181	    val = readl(TX_PWM_CTL_REG(haudio));
   182	    val &= ~(TX_PWM_CTL_PWM0_MODE_MASK | TX_PWM_CTL_PWM1_MODE_MASK);
   183	    val |= TX_PWM_CTL_PWM1_EN | TX_PWM_CTL_PWM1_DIF_EN;
   184	    writel(val, TX_PWM_CTL_REG(haudio));
   185	    break;
   186	  case AUDIO_OUTPUT_CHAN_PWM0:
   187	  default:
   188	    audio_set_pwm0(haudio);
   189	    break;
   190	  }
   191	}
