   193	void hal_audio_set_channel(hal_audio_handle_t *haudio) {
   194	  uint32_t reg_val;
   195	
   196	  reg_val = readl(TXFIFO_CTL_REG(haudio));
   197	  reg_val &= ~TXFIFO_CH_MASK;
   198	  if (haudio->init.channel == AUDIO_CHANNEL_MONO) {
   199	    reg_val |= TXFIFO_CH0_EN;
   200	  } else if (haudio->init.channel == AUDIO_CHANNEL_STEREO) {
   201	    reg_val |= TXFIFO_CH0_EN | TXFIFO_CH1_EN;
   202	  }
   203	  writel(reg_val, TXFIFO_CTL_REG(haudio));
   204	}
