   206	/**
   207	 * @brief Configures AUDIO sampling rate based on initialization parameters.
   208	 *
   209	 *        This function sets the appropriate hardware divider values and clock
   210	 * frequencies according to the samplerate parameter in the AUDIO initialization
   211	 * structure. It ensures that the audio hardware operates at the correct
   212	 * sampling frequency.
   213	 *
   214	 * @param[in,out] haudio Pointer to AUDIO handle structure
   215	 *
   216	 * @note This function is internally used by the audio driver and should not be
   217	 * called directly. It assumes that the AUDIO handle has been properly
   218	 * initialized.
   219	 *
   220	 * @warning Do not call this function from an interrupt context.
   221	 */
   222	void hal_audio_set_samplerate(hal_audio_handle_t *haudio) {
   223	  uint32_t val, module_freq, hw_rate = 0;
   224	
   225	  if (!haudio)
   226	    return;
   227	  /* Get frequency division factor */
   228	  switch (haudio->init.samplerate) {
   229	  case AUDIO_SAMPLERATE_48000:
   230	  case AUDIO_SAMPLERATE_44100:
   231	    hw_rate = 0;
   232	    break;
   233	  case AUDIO_SAMPLERATE_32000:
   234	    hw_rate = 1;
   235	    break;
   236	  case AUDIO_SAMPLERATE_24000:
   237	  case ADUIO_SAMPLERATE_22050:
   238	    hw_rate = 2;
   239	    break;
   240	  case ADUIO_SAMPLERATE_16000:
   241	    hw_rate = 3;
   242	    break;
   243	  case ADUIO_SAMPLERATE_11025:
   244	  case ADUIO_SAMPLERATE_12000:
   245	    hw_rate = 4;
   246	    break;
   247	  case ADUIO_SAMPLERATE_8000:
   248	    hw_rate = 5;
   249	    break;
   250	  default:
   251	    break;
   252	  }
   253	  /* Set playback samplerate */
   254	  val = readl(TX_PLAYBACK_CTL_REG(haudio));
   255	  val &= ~TX_PLAYBACK_CTL_FS_OUT_MASK;
   256	  val |= TX_PLAYBACK_CTL_FS_OUT(hw_rate);
   257	  writel(val, TX_PLAYBACK_CTL_REG(haudio));
   258	  /* Get module frequency */
   259	  switch (haudio->init.samplerate) {
   260	  case AUDIO_SAMPLERATE_48000:
   261	  case AUDIO_SAMPLERATE_32000:
   262	  case AUDIO_SAMPLERATE_24000:
   263	  case ADUIO_SAMPLERATE_16000:
   264	  case ADUIO_SAMPLERATE_12000:
   265	  case ADUIO_SAMPLERATE_8000:
   266	    module_freq = AUDIO_FREQ_24576000;
   267	    break;
   268	  case AUDIO_SAMPLERATE_44100:
   269	  case ADUIO_SAMPLERATE_22050:
   270	  case ADUIO_SAMPLERATE_11025:
   271	    module_freq = AUDIO_FREQ_22579200;
   272	    break;
   273	  default:
   274	    module_freq = 0;
   275	  }
   276	  hal_clk_set_freq(CLK_AUDIO_SCLK, module_freq);
   277	}
