   300	  haudio->errcode = 0;
   301	  haudio->state = AUDIO_STATE_RESET;
   302	  haudio->ptxbuffer = NULL;
   303	  haudio->tx_xfer_size = 0;
   304	  haudio->tx_xfer_count = 0;
   305	  haudio->txdma = NULL;
   306	  haudio->init_cb = NULL;
   307	  haudio->deinit_cb = NULL;
   308	  haudio->tx_interrupt_cb = NULL;
   309	  haudio->tx_dma_cb = NULL;
   310	  haudio->xfer_error_cb = NULL;
   311	  haudio->xfer_abort_cb = NULL;
   312	
   313	  haudio->init.target_volume = ADUIO_DEFAULT_TAR_VOLUME;
   314	  haudio->init.fade_step = AUDIO_DEFAULT_FADE_STEP;
   315	  haudio->init.fade_speed = AUDIO_DEFAULT_FADE_SPEED;
   316	  haudio->init.dvc_volume = AUDIO_DEFAULT_DVC_VOLUME;
   317	  haudio->init.fltout_shift = AUDIO_FLTOUT_SHIFT_13BIT;
   318	  haudio->init.output_chan = AUDIO_OUTPUT_CHAN_PWM1;
   319	  haudio->init.out_mode = AUDIO_OUTPUT_MODE_PWM;
   320	  haudio->init.sdm_gain = AUDIO_SDM_GAIN_1;
   321	  haudio->init.tx_dlt = AUDIO_TX_DELAY_5MS;
   322	  /* The APP must set the following three parameters */
   323	  haudio->init.samplebits = 0;
   324	  haudio->init.samplerate = 0;
   325	  haudio->init.channel = 0;
   326	  haudio->init.flag = HAL_HANDLE_ALL_INIT_FLAG;
   327	}
