   329	/**
   330	 * @brief Initializes the AUDIO peripheral with specified parameters.
   331	 *
   332	 *        This function fully initializes the AUDIO peripheral according to the
   333	 * parameters specified in the AUDIO handle structure. It configures all
   334	 * hardware registers, sets up the audio path, and prepares the peripheral for
   335	 * data transmission.
   336	 *
   337	 * @param[in,out] haudio Pointer to AUDIO handle structure containing
   338	 * initialization parameters
   339	 *
   340	 * @return HAL_OK on successful initialization, HAL_ERROR if parameters are
   341	 * invalid, HAL_BUSY if AUDIO is busy
   342	 *
   343	 * @note This function requires that the init_cb callback is registered to
   344	 * configure clocks. The samplebits, samplerate, and channel parameters must be
   345	 * set by the application.
   346	 *
   347	 * @warning Do not call this function from an interrupt context.
   348	 */
   349	hal_status_e hal_audio_init(hal_audio_handle_t *haudio) {
   350	  uint32_t val, fade_val;
   351	  uint16_t target_vol;
   352	
   353	  if (!haudio)
   354	    return HAL_ERROR;
   355	
   356	  ASSERT_PARAM(0 != (haudio->init.flag & HAL_HANDLE_ALL_INIT_FLAG));
   357	  ASSERT_PARAM(haudio->regbase != 0);
   358	
   359	  HAL_LOCK(haudio);
   360	  if (haudio->init_cb)
   361	    /* Should set input frequency and enable clock for AUDIO in callback */
   362	    haudio->init_cb(haudio);
   363	  else {
   364	    hal_audio_clock_init();
   365	  }
   366	  /* Set audio volume */
   367	  if (haudio->init.target_volume != ADUIO_DEFAULT_TAR_VOLUME) {
   368	    target_vol = ADUIO_DEFAULT_TAR_VOLUME - haudio->init.target_volume;
   369	    if (target_vol == 100)
   370	      fade_val = 0;
   371	    else
   372	      fade_val = AUDIO_DEFAULT_FADE_VOL - (target_vol * AUDIO_DEFAULT_FADE_MAP);
   373	    val = readl(FADE_CTL1_REG(haudio));
   374	    val &= ~FADE_CTL1_TARGET_VOL_MASK;
   375	    val |= fade_val;
   376	    writel(val, FADE_CTL1_REG(haudio));
   377	  }
   378	  /* Set fade step */
   379	  if (haudio->init.fade_step != AUDIO_DEFAULT_FADE_STEP) {
   380	    val = readl(FADE_CTL0_REG(haudio));
   381	    val &= ~FADE_CTL0_FADE_STEP_MASK;
   382	    val |= haudio->init.fade_step;
   383	    writel(val, FADE_CTL0_REG(haudio));
   384	  }
   385	  /* Set fade speed */
   386	  if (haudio->init.fade_speed != AUDIO_DEFAULT_FADE_SPEED) {
   387	    val = readl(FADE_CTL0_REG(haudio));
   388	    val &= ~FADE_CTL0_FADE_SPEED_MASK;
   389	    val |= haudio->init.fade_speed;
   390	    writel(val, FADE_CTL0_REG(haudio));
   391	  }
   392	  /* Set DVC gain */
   393	  if (haudio->init.dvc_volume != AUDIO_DEFAULT_DVC_VOLUME) {
   394	    val = readl(TX_DVC3_4_CTL_REG(haudio));
   395	    val &= ~TX_DVC3_4_CTL_DVC3_GAIN_MASK;
   396	    val &= ~TX_DVC3_4_CTL_DVC4_GAIN_MASK;
   397	    val |= (haudio->init.dvc_volume << TX_DVC3_4_CTL_DVC3_GAIN_SHIFT |
   398	            haudio->init.dvc_volume << TX_DVC3_4_CTL_DVC4_GAIN_SHIFT);
   399	    writel(val, TX_DVC3_4_CTL_REG(haudio));
   400	  }
   401	  /* Set filter shift */
   402	  if (haudio->init.fltout_shift != AUDIO_FLTOUT_SHIFT_13BIT) {
   403	    val = readl(TX_PLAYBACK_CTL_REG(haudio));
   404	    val &= ~TX_PLAYBACK_CTL_FLTOUT_SHIFTN_MASK;
   405	    val |= haudio->init.fltout_shift << TX_PLAYBACK_CTL_FLTOUT_SHIFTN_SHIFT;
   406	    writel(val, TX_PLAYBACK_CTL_REG(haudio));
   407	  }
   408	  /* Set output and check output mode */
   409	  audio_set_channel(haudio);
   410	  /* Set SDM gain */
   411	  if (haudio->init.sdm_gain != AUDIO_SDM_GAIN_1) {
   412	    val = readl(TX_SDM_CTL_REG(haudio));
   413	    val &= ~(TX_SDM_CTL_TX_CH0_SDM_GAIN_A0_MASK |
   414	             TX_SDM_CTL_TX_CH0_SDM_GAIN_B0_MASK |
   415	             TX_SDM_CTL_TX_CH0_SDM_GAIN_C0_MASK |
   416	             TX_SDM_CTL_TX_CH1_SDM_GAIN_A0_MASK |
   417	             TX_SDM_CTL_TX_CH1_SDM_GAIN_B0_MASK |
   418	             TX_SDM_CTL_TX_CH1_SDM_GAIN_C0_MASK);
   419	    val |= (haudio->init.sdm_gain << TX_SDM_CTL_TX_CH0_SDM_GAIN_A0_SHIFT |
   420	            haudio->init.sdm_gain << TX_SDM_CTL_TX_CH0_SDM_GAIN_B0_SHIFT |
   421	            haudio->init.sdm_gain << TX_SDM_CTL_TX_CH0_SDM_GAIN_C0_SHIFT |
   422	            haudio->init.sdm_gain << TX_SDM_CTL_TX_CH1_SDM_GAIN_A0_SHIFT |
   423	            haudio->init.sdm_gain << TX_SDM_CTL_TX_CH1_SDM_GAIN_B0_SHIFT |
   424	            haudio->init.sdm_gain << TX_SDM_CTL_TX_CH1_SDM_GAIN_C0_SHIFT);
   425	    writel(val, TX_SDM_CTL_REG(haudio));
   426	  }
   427	  /* Check samplebits */
   428	  if (haudio->init.samplebits != AUDIO_SAMPLEBITS_16BIT) {
   429	    haudio->errcode = AUDIO_ERROR_INVALID_PARAM;
   430	    return HAL_ERROR;
   431	  }
   432	  /* Set samplerate */
   433	  hal_audio_set_samplerate(haudio);
   434	  /* Set output channel num */
   435	  val = readl(TXFIFO_CTL_REG(haudio));
   436	  val &= ~(TXFIFO_CTL_TX_FIFO_CH0_EN_MASK | TXFIFO_CTL_TX_FIFO_CH1_EN_MASK);
   437	  /* Maybe need to check the channel num, now is all fifo open */
   438	  val |= TXFIFO_CTL_TX_FIFO_CH0_EN | TXFIFO_CTL_TX_FIFO_CH1_EN;
   439	  writel(val, TXFIFO_CTL_REG(haudio));
   440	  /*Flush TXFIFO*/
   441	  val = readl(TXFIFO_CTL_REG(haudio));
   442	  val |= TXFIFO_CTL_TX_FIFO_FLUSH_MASK;
   443	  val = readl(TXFIFO_CTL_REG(haudio));
   444	
   445	  haudio->errcode = AUDIO_ERROR_NONE;
   446	  haudio->state = AUDIO_STATE_READY;
   447	  HAL_UNLOCK(haudio);
   448	
   449	  return HAL_OK;
   450	}
