   105	static bool dmic_valid_rate(uint32_t samplerate) {
   106	  static const uint32_t rates[] = {
   107	      8000, 11025, 12000, 16000, 22050, 24000, 32000, 44100, 48000,
   108	  };
   109	
   110	  for (unsigned int i = 0; i < sizeof(rates) / sizeof(rates[0]); i++) {
   111	    if (samplerate == rates[i]) {
   112	      return true;
   113	    }
   114	  }
   115	
   116	  return false;
   117	}
