   130	static uint32_t dmic_frame_bytes(uint8_t channels) {
   131	  return (uint32_t)channels * (DMIC_SAMPLE_BITS / 8);
   132	}
   133	
   134	static int dmic_parse_u32(const char *text, uint32_t *value) {
   135	  char *endptr;
   136	  unsigned long parsed;
   137	
   138	  if (text == NULL || value == NULL) {
   139	    return -EINVAL;
   140	  }
   141	
   142	  errno = 0;
   143	  parsed = strtoul(text, &endptr, 0);
   144	  if (errno != 0 || endptr == text || *endptr != '\0' ||
   145	      parsed > UINT32_MAX) {
   146	    return -EINVAL;
   147	  }
   148	
   149	  *value = (uint32_t)parsed;
   150	  return 0;
   151	}
   152	
   153	static void dmic_put_u16(uint8_t *buf, uint16_t value) {
   154	  buf[0] = (uint8_t)(value & 0xff);
   155	  buf[1] = (uint8_t)((value >> 8) & 0xff);
   156	}
   157	
   158	static void dmic_put_u32(uint8_t *buf, uint32_t value) {
   159	  buf[0] = (uint8_t)(value & 0xff);
   160	  buf[1] = (uint8_t)((value >> 8) & 0xff);
   161	  buf[2] = (uint8_t)((value >> 16) & 0xff);
   162	  buf[3] = (uint8_t)((value >> 24) & 0xff);
   163	}
   164	
   165	static void dmic_make_wav_header(uint8_t header[44], uint32_t samplerate,
   166	                                 uint8_t channels, uint32_t data_bytes) {
   167	  uint32_t byte_rate = samplerate * channels * (DMIC_SAMPLE_BITS / 8);
   168	  uint16_t block_align = channels * (DMIC_SAMPLE_BITS / 8);
   169	
   170	  memset(header, 0, 44);
   171	  memcpy(&header[0], "RIFF", 4);
   172	  dmic_put_u32(&header[4], data_bytes + 36);
   173	  memcpy(&header[8], "WAVE", 4);
   174	  memcpy(&header[12], "fmt ", 4);
   175	  dmic_put_u32(&header[16], 16);
   176	  dmic_put_u16(&header[20], 1);
   177	  dmic_put_u16(&header[22], channels);
   178	  dmic_put_u32(&header[24], samplerate);
   179	  dmic_put_u32(&header[28], byte_rate);
   180	  dmic_put_u16(&header[32], block_align);
   181	  dmic_put_u16(&header[34], DMIC_SAMPLE_BITS);
   182	  memcpy(&header[36], "data", 4);
   183	  dmic_put_u32(&header[40], data_bytes);
   184	}
   185	
   186	static int dmic_write_all(int fd, const void *buffer, size_t bytes) {
   187	  const uint8_t *ptr = buffer;
   188	
   189	  while (bytes > 0) {
   190	    ssize_t written = write(fd, ptr, bytes);
   191	    if (written < 0) {
   192	      if (errno == EINTR) {
   193	        continue;
   194	      }
   195	
   196	      return -errno;
   197	    }
   198	
   199	    if (written == 0) {
   200	      return -EIO;
   201	    }
   202	
   203	    ptr += written;
   204	    bytes -= (size_t)written;
   205	  }
   206	
   207	  return 0;
   208	}
   209	
   210	static int dmic_write_wav_header(int fd, const struct dmic_options *opts,
   211	                                 uint32_t data_bytes) {
   212	  uint8_t header[44];
   213	
   214	  dmic_make_wav_header(header, opts->samplerate, opts->channels, data_bytes);
   215	  return dmic_write_all(fd, header, sizeof(header));
   216	}
