   218	static void dmic_stats_init(struct dmic_runtime *rt) {
   219	  for (unsigned int i = 0; i < DMIC_DEFAULT_CHANNELS; i++) {
   220	    rt->stats[i].min = INT16_MAX;
   221	    rt->stats[i].max = INT16_MIN;
   222	    rt->stats[i].peak = 0;
   223	    rt->stats[i].sum_abs = 0;
   224	    rt->stats[i].samples = 0;
   225	    rt->stats[i].nonzero = 0;
   226	  }
   227	}
   228	
   229	static void dmic_stats_add(struct dmic_channel_stats *stats, int16_t sample) {
   230	  int32_t value = sample;
   231	  uint32_t absval = value < 0 ? (uint32_t)(-value) : (uint32_t)value;
   232	
   233	  if (sample < stats->min) {
   234	    stats->min = sample;
   235	  }
   236	
   237	  if (sample > stats->max) {
   238	    stats->max = sample;
   239	  }
   240	
   241	  if (absval > stats->peak) {
   242	    stats->peak = absval;
   243	  }
   244	
   245	  if (sample != 0) {
   246	    stats->nonzero++;
   247	  }
   248	
   249	  stats->sum_abs += absval;
   250	  stats->samples++;
   251	}
   252	
   253	static void dmic_process_period(struct dmic_runtime *rt, uint8_t *period) {
   254	  int16_t *samples = (int16_t *)period;
   255	  size_t sample_count = rt->period_bytes / sizeof(int16_t);
   256	  uint8_t channels = rt->channels;
   257	
   258	  for (size_t i = 0; i + channels <= sample_count; i += channels) {
   259	    dmic_stats_add(&rt->stats[0], samples[i]);
   260	    if (channels == 2) {
   261	      dmic_stats_add(&rt->stats[1], samples[i + 1]);
   262	    }
   263	  }
   264	}
   265	
   266	static void dmic_print_stats(const struct dmic_runtime *rt,
   267	                             const struct dmic_options *opts) {
   268	  uint64_t frames = rt->data_bytes / dmic_frame_bytes(opts->channels);
   269	
   270	  printf("dmic: done rate=%" PRIu32 " channels=%u bits=%u bytes=%" PRIu64
   271	         " frames=%" PRIu64 " periods=%" PRIu32,
   272	         opts->samplerate, opts->channels, DMIC_SAMPLE_BITS, rt->data_bytes,
   273	         frames, rt->processed_periods);
   274	
   275	  if (rt->lost_periods != 0) {
   276	    printf(" lost=%" PRIu32, rt->lost_periods);
   277	  }
   278	
   279	  printf("\n");
   280	
   281	  for (uint8_t ch = 0; ch < opts->channels; ch++) {
   282	    const struct dmic_channel_stats *stats = &rt->stats[ch];
   283	    uint64_t mean_abs = stats->samples == 0 ? 0 :
   284	                        stats->sum_abs / stats->samples;
   285	    char name = ch == 0 ? 'L' : 'R';
   286	
   287	    printf("dmic: %c samples=%" PRIu64 " min=%" PRId16 " max=%" PRId16
   288	           " peak=%" PRIu32 " mean_abs=%" PRIu64 " nonzero=%" PRIu64 "\n",
   289	           name, stats->samples, stats->min, stats->max, stats->peak,
   290	           mean_abs, stats->nonzero);
   291	  }
   292	}
