   294	static void dmic_period_callback(hal_audio_handle_t *haudio) {
   295	  struct dmic_runtime *rt = g_dmic_active;
   296	  uint32_t slot;
   297	
   298	  if (rt == NULL || &rt->audio != haudio) {
   299	    return;
   300	  }
   301	
   302	  slot = rt->next_slot % DMIC_BUFFER_PERIODS;
   303	  rt->ready[slot]++;
   304	  rt->next_slot++;
   305	}
