   307	static int dmic_dma_prepare(struct dmic_runtime *rt,
   308	                            const struct dmic_options *opts) {
   309	  hal_dma_handle_t *hdma = &rt->rxchan.hal;
   310	  hal_dma_data_width_e width;
   311	  int ret;
   312	
   313	  ret = drv_dma_init();
   314	  if (ret < 0) {
   315	    fprintf(stderr, "dmic: drv_dma_init failed: %d\n", ret);
   316	    return ret;
   317	  }
   318	
   319	  hal_dma_handle_init(hdma);
   320	  hdma->regbase = DMA_BASE;
   321	  hdma->init.channel_id = CONFIG_AIC_DMIC_CMD_DMA_CHANNEL;
   322	  hdma->work_mode = DMA_WORK_MODE_CYCLIC;
   323	  hdma->cyclic_period_len = rt->period_bytes;
   324	  hdma->init.direction = DMA_DEVICE_TO_MEMORY;
   325	  hdma->init.src_dev = HAL_DMA_ID_AUDIO;
   326	  hdma->init.src_mode = DMA_MODE_HANDSHAKE;
   327	  hdma->init.src_burst = DMA_XFER_BURST_1;
   328	  hdma->init.src_addr_mode = DMA_ADDR_FIXED_MODE;
   329	
   330	  width = opts->channels == 1 ? DMA_DATA_WIDTH_2_BYTES :
   331	                                DMA_DATA_WIDTH_4_BYTES;
   332	  hdma->init.src_data_width = width;
   333	  hdma->init.snk_dev = HAL_DMA_ID_SRAM;
   334	  hdma->init.snk_mode = DMA_MODE_WAIT;
   335	  hdma->init.snk_burst = DMA_XFER_BURST_1;
   336	  hdma->init.snk_addr_mode = DMA_ADDR_LINEAR_MODE;
   337	  hdma->init.snk_data_width = width;
   338	  hdma->init.flag = HAL_HANDLE_ALL_INIT_FLAG;
   339	
   340	  if (hal_dma_init(hdma) != HAL_OK) {
   341	    fprintf(stderr, "dmic: hal_dma_init failed: state=%u err=%u\n",
   342	            (unsigned int)hal_dma_get_state(hdma),
   343	            (unsigned int)hal_dma_get_error(hdma));
   344	    return -EIO;
   345	  }
   346	
   347	  rt->dma_inited = true;
   348	
   349	  ret = aic_dma_chan_register(&rt->rxchan.chan);
   350	  if (ret < 0) {
   351	    fprintf(stderr, "dmic: aic_dma_chan_register failed: %d\n", ret);
   352	    return ret;
   353	  }
   354	
   355	  rt->dma_registered = true;
   356	  return 0;
   357	}
