   387	static void dmic_cleanup(struct dmic_runtime *rt) {
   388	  if (rt->started) {
   389	    g_dmic_active = NULL;
   390	    hal_audio_stop_dmic_dma(&rt->audio);
   391	    rt->started = false;
   392	  }
   393	
   394	  if (rt->audio_inited) {
   395	    hal_audio_unregister_callback(&rt->audio, AUDIO_CB_RX_DMA, NULL);
   396	    hal_audio_deinit(&rt->audio);
   397	    rt->audio_inited = false;
   398	  }
   399	
   400	  if (rt->dma_registered) {
   401	    aic_dma_chan_unregister(&rt->rxchan.chan);
   402	    rt->dma_registered = false;
   403	  }
   404	
   405	  if (rt->dma_inited) {
   406	    hal_dma_deinit(&rt->rxchan.hal);
   407	    rt->dma_inited = false;
   408	  }
   409	
   410	  if (rt->fd >= 0) {
   411	    close(rt->fd);
   412	    rt->fd = -1;
   413	  }
   414	
   415	  free(rt->buffer);
   416	  rt->buffer = NULL;
   417	}
