   419	static int dmic_open_output(struct dmic_runtime *rt,
   420	                            const struct dmic_options *opts) {
   421	  int ret;
   422	
   423	  rt->fd = -1;
   424	  if (opts->outfile == NULL) {
   425	    return 0;
   426	  }
   427	
   428	  rt->fd = open(opts->outfile, O_WRONLY | O_CREAT | O_TRUNC, 0644);
   429	  if (rt->fd < 0) {
   430	    ret = -errno;
   431	    fprintf(stderr, "dmic: open %s failed: %d\n", opts->outfile, -ret);
   432	    return ret;
   433	  }
   434	
   435	  if (opts->wav) {
   436	    ret = dmic_write_wav_header(rt->fd, opts, 0);
   437	    if (ret < 0) {
   438	      fprintf(stderr, "dmic: write wav header failed: %d\n", -ret);
   439	      return ret;
   440	    }
   441	  }
   442	
   443	  return 0;
   444	}
   445	
   446	static int dmic_finish_output(struct dmic_runtime *rt,
   447	                              const struct dmic_options *opts) {
   448	  int ret;
   449	
   450	  if (rt->fd < 0) {
   451	    return 0;
   452	  }
   453	
   454	  if (opts->wav) {
   455	    if (lseek(rt->fd, 0, SEEK_SET) < 0) {
   456	      ret = -errno;
   457	      fprintf(stderr, "dmic: seek wav header failed: %d\n", -ret);
   458	      return ret;
   459	    }
   460	
   461	    ret = dmic_write_wav_header(rt->fd, opts, (uint32_t)rt->data_bytes);
   462	    if (ret < 0) {
   463	      fprintf(stderr, "dmic: update wav header failed: %d\n", -ret);
   464	      return ret;
   465	    }
   466	  }
   467	
   468	  return 0;
   469	}
   470	
   471	static int dmic_handle_period(struct dmic_runtime *rt,
   472	                              const struct dmic_options *opts,
   473	                              unsigned int slot) {
   474	  uint8_t *period = rt->buffer + slot * rt->period_bytes;
   475	  int ret;
   476	
   477	  up_invalidate_dcache((uintptr_t)period,
   478	                       (uintptr_t)period + rt->period_bytes);
   479	
   480	  if (rt->fd >= 0) {
   481	    ret = dmic_write_all(rt->fd, period, rt->period_bytes);
   482	    if (ret < 0) {
   483	      fprintf(stderr, "dmic: write %s failed: %d\n", opts->outfile, -ret);
   484	      return ret;
   485	    }
   486	  }
   487	
   488	  dmic_process_period(rt, period);
   489	  rt->data_bytes += rt->period_bytes;
   490	  rt->processed_periods++;
   491	  return 0;
   492	}
   493	
   494	static int dmic_capture_wait(struct dmic_runtime *rt,
   495	                             const struct dmic_options *opts,
   496	                             uint32_t target_periods) {
   497	  uint32_t done[DMIC_BUFFER_PERIODS] = {0};
   498	  uint32_t period_events = 0;
   499	  uint32_t idle_us = 0;
   500	
   501	  while ((target_periods == 0 || period_events < target_periods) &&
   502	         !g_dmic_stop) {
   503	    bool progressed = false;
   504	
   505	    for (unsigned int slot = 0; slot < DMIC_BUFFER_PERIODS; slot++) {
   506	      uint32_t ready = rt->ready[slot];
   507	      uint32_t delta = ready - done[slot];
   508	
   509	      if (delta == 0) {
   510	        continue;
   511	      }
   512	
   513	      if (delta > 1) {
   514	        uint32_t skipped = delta - 1;
   515	        rt->lost_periods += skipped;
   516	        period_events += skipped;
   517	        done[slot] = ready - 1;
   518	      }
   519	
   520	      if (target_periods != 0 && period_events >= target_periods) {
   521	        break;
   522	      }
   523	
   524	      if (dmic_handle_period(rt, opts, slot) < 0) {
   525	        return -EIO;
   526	      }
   527	
   528	      done[slot] = ready;
   529	      period_events++;
   530	      progressed = true;
   531	    }
   532	
   533	    if (progressed) {
   534	      idle_us = 0;
   535	      continue;
   536	    }
   537	
   538	    usleep(DMIC_POLL_US);
   539	    idle_us += DMIC_POLL_US;
   540	    if (idle_us >= DMIC_NO_DATA_TIMEOUT_US) {
   541	      fprintf(stderr, "dmic: timeout waiting for DMA period interrupt\n");
   542	      return -ETIMEDOUT;
   543	    }
   544	  }
   545	
   546	  return 0;
   547	}
   548	
   549	static int dmic_validate_options(struct dmic_options *opts) {
   550	  uint32_t frame_bytes = dmic_frame_bytes(opts->channels);
   551	
   552	  if (!dmic_valid_rate(opts->samplerate)) {
   553	    fprintf(stderr, "dmic: unsupported samplerate %" PRIu32 "\n",
   554	            opts->samplerate);
   555	    return -EINVAL;
   556	  }
   557	
   558	  if (opts->channels != 1 && opts->channels != 2) {
   559	    fprintf(stderr, "dmic: channels must be 1 or 2\n");
   560	    return -EINVAL;
   561	  }
   562	
   563	  if (opts->period_bytes == 0) {
   564	    opts->period_bytes = DMIC_DEFAULT_PERIOD_BYTES;
   565	  }
   566	
   567	  if ((opts->period_bytes % CACHE_LINE_SIZE) != 0 ||
   568	      (opts->period_bytes % frame_bytes) != 0) {
   569	    fprintf(stderr,
   570	            "dmic: period_bytes must align to %u and frame size %" PRIu32 "\n",
   571	            CACHE_LINE_SIZE, frame_bytes);
   572	    return -EINVAL;
   573	  }
   574	
   575	  if (opts->outfile != NULL && dmic_path_is_wav(opts->outfile)) {
   576	    opts->wav = true;
   577	  }
   578	
   579	  return 0;
   580	}
