   582	static int dmic_parse_args(int argc, char *argv[], struct dmic_options *opts) {
   583	  int ch;
   584	
   585	  opts->samplerate = DMIC_DEFAULT_RATE;
   586	  opts->channels = DMIC_DEFAULT_CHANNELS;
   587	  opts->seconds = DMIC_DEFAULT_SECONDS;
   588	  opts->period_bytes = DMIC_DEFAULT_PERIOD_BYTES;
   589	  opts->outfile = NULL;
   590	  opts->wav = false;
