int hal_audio_init(aic_audio_ctrl *codec)
{
    int ret;
    codec->reg_base = AUDIO_BASE;
    codec->irq_num = AUDIO_IRQn;
    codec->clk_id = CLK_CODEC;

    ret = hal_clk_set_freq(codec->clk_id, DEFAULT_AUDIO_FREQ);
