    ret = hal_clk_disable_assertrst(codec->clk_id);
    if (ret)
        hal_log_err("Audio uninit error!\n");

    return ret;
}

static int hal_audio_get_hw_rate(aic_audio_ctrl *codec, uint32_t samplerate)
{
    switch (samplerate)
    {
    case 48000:
    case 44100:
        return 0;
    case 32000:
        return 1;
    case 24000:
    case 22050:
        return 2;
    case 16000:
