   334	 * @warning Do not call this function from an interrupt context.
   335	 */
   336	void hal_audio_set_samplerate(hal_audio_handle_t *haudio) {
   337	  uint32_t val, module_freq, hw_rate = 0;
   338	
   339	  if (!haudio)
   340	    return;
   341	  /* Get frequency division factor */
   342	  switch (haudio->init.samplerate) {
   343	  case AUDIO_SAMPLERATE_48000:
   344	  case AUDIO_SAMPLERATE_44100:
   345	    hw_rate = 0;
   346	    break;
   347	  case AUDIO_SAMPLERATE_32000:
   348	    hw_rate = 1;
   349	    break;
   350	  case AUDIO_SAMPLERATE_24000:
   351	  case ADUIO_SAMPLERATE_22050:
   352	    hw_rate = 2;
   353	    break;
   354	  case ADUIO_SAMPLERATE_16000:
   355	    hw_rate = 3;
   356	    break;
   357	  case ADUIO_SAMPLERATE_11025:
   358	  case ADUIO_SAMPLERATE_12000:
   359	    hw_rate = 4;
   360	    break;
   361	  case ADUIO_SAMPLERATE_8000:
   362	    hw_rate = 5;
   363	    break;
   364	  default:
   365	    break;
   366	  }
   367	  /* Set playback samplerate */
   368	  val = readl(TX_PLAYBACK_CTL_REG(haudio));
   369	  val &= ~TX_PLAYBACK_CTL_FS_OUT_MASK;
   370	  val |= TX_PLAYBACK_CTL_FS_OUT(hw_rate);
   371	  writel(val, TX_PLAYBACK_CTL_REG(haudio));
   372	
   373	  /* Set DMIC samplerate */
   374	  val = readl(RX_DMIC_IF_CTRL_REG(haudio));
   375	  val &= ~RX_DMIC_IF_FS_IN_MASK;
   376	  val |= RX_DMIC_IF_FS_IN(hw_rate);
   377	  writel(val, RX_DMIC_IF_CTRL_REG(haudio));
   378	
   379	  /* Get module frequency */
   380	  switch (haudio->init.samplerate) {
   381	  case AUDIO_SAMPLERATE_48000:
   382	  case AUDIO_SAMPLERATE_32000:
   383	  case AUDIO_SAMPLERATE_24000:
   384	  case ADUIO_SAMPLERATE_16000:
   385	  case ADUIO_SAMPLERATE_12000:
   386	  case ADUIO_SAMPLERATE_8000:
   387	    val = readl(TX_PLAYBACK_CTL_REG(haudio));
   388	    val &= ~TX_PLAYBACK_CTL_CLK_MASK;
   389	    writel(val, TX_PLAYBACK_CTL_REG(haudio));
   390	
   391	    val = readl(RX_DMIC_IF_CTRL_REG(haudio));
   392	    val &= ~RX_DMIC_IF_RX_CLK_MASK;
   393	    writel(val, RX_DMIC_IF_CTRL_REG(haudio));
   394	
   395	    module_freq = AUDIO_FREQ_24576000;
   396	    break;
   397	  case AUDIO_SAMPLERATE_44100:
   398	  case ADUIO_SAMPLERATE_22050:
   399	  case ADUIO_SAMPLERATE_11025:
   400	    val = readl(TX_PLAYBACK_CTL_REG(haudio));
   401	    val |= TX_PLAYBACK_CTL_CLK_22579KHZ;
   402	    writel(val, TX_PLAYBACK_CTL_REG(haudio));
   403	
   404	    val = readl(RX_DMIC_IF_CTRL_REG(haudio));
   405	    val |= RX_DMIC_IF_RX_CLK_22579KHZ;
   406	    writel(val, RX_DMIC_IF_CTRL_REG(haudio));
   407	
   408	    module_freq = AUDIO_FREQ_22579200;
   409	    break;
   410	  default:
   411	    module_freq = 0;
   412	  }
   413	  hal_clk_set_freq(CLK_AUDIO_SCLK, module_freq);
   414	}
