 *
 * @warning Do not call this function from an interrupt context.
 */
hal_status_e hal_audio_transmit_dma(hal_audio_handle_t *haudio,
                                    const uint8_t *pdata, uint32_t size) {
  hal_status_e ret = HAL_OK;
  uint32_t val;

  ASSERT_PARAM(haudio);
  ASSERT_PARAM(haudio->regbase != 0);

  if ((!pdata) || (size == 0))
    return HAL_ERROR;

  /* Clean TX counter */
  writel(0x0, TX_CNT_REG(haudio));

  if (haudio->state == AUDIO_STATE_READY) {
    HAL_LOCK(haudio);

    haudio->state = AUDIO_STATE_BUSY_TX;
    haudio->errcode = AUDIO_ERROR_NONE;
    haudio->ptxbuffer = pdata;
    haudio->tx_xfer_size = size;
    haudio->tx_xfer_count = size;
    /* Set the DMA Tx abort callback */
    haudio->txdma->xfer_abort_cb = NULL;

    ret = hal_dma_registger_callback(haudio->txdma,
                     DMA_CB_XFER_HALF_TASK_COMPLETE_CB,
                     NULL);
    if (ret != HAL_OK) {
      haudio->state = AUDIO_STATE_ERROR;
      haudio->errcode = AUDIO_ERROR_DMA;
      HAL_UNLOCK(haudio);
      return ret;
    }

    ret = hal_dma_registger_callback(haudio->txdma,
                                     DMA_CB_XFER_FULL_TASK_COMPLETE_CB,
                                     NULL);
    if (ret != HAL_OK) {
      haudio->state = AUDIO_STATE_ERROR;
      haudio->errcode = AUDIO_ERROR_DMA;
      HAL_UNLOCK(haudio);
      return ret;
    }

    ret = hal_dma_registger_callback(haudio->txdma,
                                     DMA_CB_XFER_ALL_TASKS_COMPLETE_CB,
                                     audio_dma_full_task_callback);
    if (ret != HAL_OK) {
      haudio->state = AUDIO_STATE_ERROR;
      haudio->errcode = AUDIO_ERROR_DMA;
      HAL_UNLOCK(haudio);
      return ret;
    }
    /* Enable the Tx DMA Stream */
    ret = hal_dma_start_it(haudio->txdma, (uint32_t)haudio->ptxbuffer,
                           TXFIFO_DATA_REG(haudio), size);
    if (ret != HAL_OK) {
      auderr("Failed to start AUDIO DMA transmission");
      haudio->state = AUDIO_STATE_ERROR;
      haudio->errcode = AUDIO_ERROR_DMA;
      HAL_UNLOCK(haudio);
      return ret;
    }
    /* Enable Audio Tx DMA request */
    val = readl(FIFO_INT_EN_REG(haudio));
    val |= FIFO_INT_EN_AUDOUT_DRQ_EN;
    writel(val, FIFO_INT_EN_REG(haudio));
    /* Check if the Audio is already enabled */
    val = readl(GLOBE_CTL_REG(haudio));
    if ((val & GLOBE_CTL_TX_GLBEN) == 0) {
      val |= GLOBE_CTL_TX_GLBEN;
      writel(val, GLOBE_CTL_REG(haudio));
    }
    HAL_UNLOCK(haudio);

    return HAL_OK;
  } else {
    auderr("AUDIO is busy, cannot start DMA transmission");
    return HAL_BUSY;
  }
}

hal_status_e hal_audio_receive_dmic_dma(hal_audio_handle_t *haudio,
                                        uint8_t *pdata, uint32_t size,
                                        uint32_t period_len) {
  hal_status_e ret = HAL_OK;
  uint32_t frame_bytes;

  ASSERT_PARAM(haudio);
  ASSERT_PARAM(haudio->regbase != 0);

  if ((!haudio) || (!pdata) || (size == 0) || (period_len == 0) ||
      (haudio->rxdma == NULL)) {
    return HAL_ERROR;
  }

  if (haudio->init.samplebits != AUDIO_SAMPLEBITS_16BIT) {
    haudio->errcode = AUDIO_ERROR_INVALID_PARAM;
    return HAL_ERROR;
  }

  if (haudio->init.channel == AUDIO_CHANNEL_MONO) {
    frame_bytes = 2;
  } else if (haudio->init.channel == AUDIO_CHANNEL_STEREO) {
    frame_bytes = 4;
  } else {
    haudio->errcode = AUDIO_ERROR_INVALID_PARAM;
    return HAL_ERROR;
  }

  if ((period_len % frame_bytes) != 0 || (size % period_len) != 0) {
    haudio->errcode = AUDIO_ERROR_INVALID_PARAM;
    return HAL_ERROR;
  }

  if (haudio->state != AUDIO_STATE_READY) {
    return HAL_BUSY;
  }

  HAL_LOCK(haudio);

  haudio->state = AUDIO_STATE_BUSY_RX;
  haudio->errcode = AUDIO_ERROR_NONE;
  haudio->prxbuffer = pdata;
  haudio->rx_xfer_size = size;
  haudio->rx_xfer_count = size;
  haudio->rxdma->parent = haudio;

  ret = hal_dma_registger_callback(haudio->rxdma,
                                   DMA_CB_XFER_HALF_TASK_COMPLETE_CB, NULL);
  if (ret != HAL_OK) {
    goto errout;
  }

  ret = hal_dma_registger_callback(haudio->rxdma,
                                   DMA_CB_XFER_FULL_TASK_COMPLETE_CB,
                                   audio_dmic_dma_period_callback);
  if (ret != HAL_OK) {
    goto errout;
  }

  ret = hal_dma_registger_callback(haudio->rxdma,
                                   DMA_CB_XFER_ALL_TASKS_COMPLETE_CB, NULL);
  if (ret != HAL_OK) {
    goto errout;
  }

  writel(0x0, DMIC_RX_CNT_REG(haudio));
  hal_audio_set_samplerate(haudio);
  hal_audio_set_dmic_channel(haudio);

  ret = hal_dma_start_it(haudio->rxdma, DMIC_RXFIFO_DATA_REG(haudio),
                         (uint32_t)haudio->prxbuffer, size);
  if (ret != HAL_OK) {
    auderr("Failed to start DMIC DMA reception\n");
    goto errout;
  }

  hal_audio_flush_dmic_fifo(haudio);
  hal_audio_enable_rx_global(haudio);
  hal_audio_enable_dmic_adout_shift(haudio);
  hal_audio_enable_dmic_drq(haudio);

  HAL_UNLOCK(haudio);
  return HAL_OK;

errout:
  haudio->state = AUDIO_STATE_ERROR;
  haudio->errcode = AUDIO_ERROR_DMA;
  HAL_UNLOCK(haudio);
  return ret == HAL_OK ? HAL_ERROR : ret;
}

hal_status_e hal_audio_stop_dmic_dma(hal_audio_handle_t *haudio) {
  hal_status_e status = HAL_OK;

  if (!haudio) {
    return HAL_ERROR;
  }

  HAL_LOCK(haudio);

  hal_audio_disable_dmic_drq(haudio);
  hal_audio_disable_rx_global(haudio);

  if (haudio->rxdma != NULL && hal_dma_get_state(haudio->rxdma) ==
                                    DMA_STATE_BUSY) {
    if (hal_dma_abort_it(haudio->rxdma) != HAL_OK) {
      haudio->errcode |= AUDIO_ERROR_DMA;
      status = HAL_ERROR;
    }
  }

  hal_audio_flush_dmic_fifo(haudio);
  haudio->state = AUDIO_STATE_READY;

  HAL_UNLOCK(haudio);
  return status;
}

