    audio_set_pwm0(haudio);
    audio_set_pwm1(haudio);
    val = readl(TX_PWM_CTL_REG(haudio));
    val &= ~(TX_PWM_CTL_PWM0_MODE_MASK | TX_PWM_CTL_PWM1_MODE_MASK);
    val |= TX_PWM_CTL_PWM0_EN | TX_PWM_CTL_PWM0_DIF_EN;
