    hdma->errcode = DMA_ERROR_ADDRESS_ALIGN;
    auderr("DMA address is not aligned"
           " src=0x%08x dst=0x%08x align_mask=0x%08x\n",
           src, dst, (unsigned int)DMA_ADDR_ALIGN_MASK);
    return HAL_ERROR;
