static inline void hal_audio_disable_fade_ch1(aic_audio_ctrl *codec)
{
    uint32_t reg_val;

    reg_val = readl(codec->reg_base + FADE_CTRL0_REG);
    reg_val &= ~FADE_CTRL0_CH1_EN;
    writel(reg_val, codec->reg_base + FADE_CTRL0_REG);
