    for (unsigned int slot = 0; slot < DMIC_BUFFER_PERIODS; slot++) {
      uint32_t ready = rt->ready[slot];
      uint32_t delta = ready - done[slot];

      if (delta == 0) {
        continue;
      }

      if (delta > 1) {
        uint32_t skipped = delta - 1;
        rt->lost_periods += skipped;
        period_events += skipped;
