static int dmic_validate_options(struct dmic_options *opts) {
  uint32_t frame_bytes = dmic_frame_bytes(opts->channels);

  if (!dmic_valid_rate(opts->samplerate)) {
    fprintf(stderr, "dmic: unsupported samplerate %" PRIu32 "\n",
            opts->samplerate);
    return -EINVAL;
