 *
 * @note This function should only be called when DMA is in BUSY state
 */
hal_status_e hal_dma_abort(hal_dma_handle_t *hdma) {
  uint32_t ch;

  if (!hdma) {
    return HAL_ERROR;
  }

  HAL_LOCK(hdma);

  if (hdma->init.channel_id >= DMA_MAX_CHANNEL_NUM) {
    hdma->errcode = DMA_ERROR_CHAN_NO_EXIST;
    HAL_UNLOCK(hdma);
    return HAL_ERROR;
