static int hal_audio_get_hw_rate(aic_audio_ctrl *codec, uint32_t samplerate)
{
    switch (samplerate)
    {
    case 48000:
    case 44100:
        return 0;
    case 32000:
        return 1;
    case 24000:
    case 22050:
        return 2;
    case 16000:
        return 3;
    case 12000:
    case 11025:
        return 4;
    case 8000:
