static inline void hal_audio_flush_tx_fifo(aic_audio_ctrl *codec)
{
    uint32_t reg_val;

    reg_val = readl(codec->reg_base + TXFIFO_CTRL_REG);
    reg_val |= TXFIFO_FLUSH;
    writel(reg_val, codec->reg_base + TXFIFO_CTRL_REG);
}

