hal_status_e hal_audio_receive_dmic_dma(hal_audio_handle_t *haudio,
                                        uint8_t *pdata, uint32_t size,
                                        uint32_t period_len) {
  hal_status_e ret = HAL_OK;
  uint32_t frame_bytes;

  ASSERT_PARAM(haudio);
  ASSERT_PARAM(haudio->regbase != 0);

  if ((!haudio) || (!pdata) || (size == 0) || (period_len == 0) ||
      (haudio->rxdma == NULL)) {
    return HAL_ERROR;
  }

  if (haudio->init.samplebits != AUDIO_SAMPLEBITS_16BIT) {
    haudio->errcode = AUDIO_ERROR_INVALID_PARAM;
    return HAL_ERROR;
  }

  if (haudio->init.channel == AUDIO_CHANNEL_MONO) {
    frame_bytes = 2;
  } else if (haudio->init.channel == AUDIO_CHANNEL_STEREO) {
    frame_bytes = 4;
  } else {
    haudio->errcode = AUDIO_ERROR_INVALID_PARAM;
    return HAL_ERROR;
  }

  if ((period_len % frame_bytes) != 0 || (size % period_len) != 0) {
    haudio->errcode = AUDIO_ERROR_INVALID_PARAM;
    return HAL_ERROR;
  }

  if (haudio->state != AUDIO_STATE_READY) {
    return HAL_BUSY;
  }

  HAL_LOCK(haudio);

  haudio->state = AUDIO_STATE_BUSY_RX;
  haudio->errcode = AUDIO_ERROR_NONE;
  haudio->prxbuffer = pdata;
  haudio->rx_xfer_size = size;
  haudio->rx_xfer_count = size;
  haudio->rxdma->parent = haudio;

  ret = hal_dma_registger_callback(haudio->rxdma,
                                   DMA_CB_XFER_HALF_TASK_COMPLETE_CB, NULL);
  if (ret != HAL_OK) {
    goto errout;
  }

  ret = hal_dma_registger_callback(haudio->rxdma,
                                   DMA_CB_XFER_FULL_TASK_COMPLETE_CB,
                                   audio_dmic_dma_period_callback);
  if (ret != HAL_OK) {
    goto errout;
  }

  ret = hal_dma_registger_callback(haudio->rxdma,
                                   DMA_CB_XFER_ALL_TASKS_COMPLETE_CB, NULL);
  if (ret != HAL_OK) {
    goto errout;
  }

  writel(0x0, DMIC_RX_CNT_REG(haudio));
  hal_audio_set_samplerate(haudio);
  hal_audio_set_dmic_channel(haudio);

  ret = hal_dma_start_it(haudio->rxdma, DMIC_RXFIFO_DATA_REG(haudio),
                         (uint32_t)haudio->prxbuffer, size);
  if (ret != HAL_OK) {
    auderr("Failed to start DMIC DMA reception\n");
    goto errout;
  }

  hal_audio_flush_dmic_fifo(haudio);
  hal_audio_enable_rx_global(haudio);
  hal_audio_enable_dmic_adout_shift(haudio);
  hal_audio_enable_dmic_drq(haudio);

  HAL_UNLOCK(haudio);
  return HAL_OK;

errout:
  haudio->state = AUDIO_STATE_ERROR;
  haudio->errcode = AUDIO_ERROR_DMA;
  HAL_UNLOCK(haudio);
  return ret == HAL_OK ? HAL_ERROR : ret;
}

