static void aic_reset_set(u32 rst_id, unsigned int assert) {
  unsigned int value;

  value = readl(cmu_reg(aic_reset_signals[rst_id].offset));
  if (assert)
    value &= ~aic_reset_signals[rst_id].bit;
  else
    value |= aic_reset_signals[rst_id].bit;
  writel(value, cmu_reg(aic_reset_signals[rst_id].offset));
}

