  static const uint32_t rates[] = {
      8000, 11025, 12000, 16000, 22050, 24000, 32000, 44100, 48000,
  };

  for (unsigned int i = 0; i < sizeof(rates) / sizeof(rates[0]); i++) {
    if (samplerate == rates[i]) {
