  uint16_t block_align = channels * (DMIC_SAMPLE_BITS / 8);

  memset(header, 0, 44);
  memcpy(&header[0], "RIFF", 4);
  dmic_put_u32(&header[4], data_bytes + 36);
  memcpy(&header[8], "WAVE", 4);
  memcpy(&header[12], "fmt ", 4);
  dmic_put_u32(&header[16], 16);
  dmic_put_u16(&header[20], 1);
