static int dmic_write_all(int fd, const void *buffer, size_t bytes) {
  const uint8_t *ptr = buffer;

  while (bytes > 0) {
    ssize_t written = write(fd, ptr, bytes);
    if (written < 0) {
      if (errno == EINTR) {
        continue;
      }

      return -errno;
    }

    if (written == 0) {
      return -EIO;
    }

    ptr += written;
    bytes -= (size_t)written;
  }

  return 0;
}

