static int aic_audio_start(FAR struct audio_lowerhalf_s *dev) {
  struct aic_audio_s *priv = (struct aic_audio_s *)dev;

  if (priv->started) {
    return OK;
  }

  priv->tone_phase = 0;
  priv->xrun = false;

  if (priv->alloc_addr == NULL) {
    auderr("audio start failed: no dma buffers allocated\n");
    return -ENOMEM;
  }

