/* audio_playback.c — Audio playback via Vela media_player API.
 *
 * Writes PCM to a temp file then plays it via media_player URL mode.
 * Buffer mode (media_player_write_data) hangs on some platforms,
 * so we use the file-based approach for reliability. */

#include "voice/audio_playback.h"
#include "velaclaw_config.h"

#include <errno.h>
#include <fcntl.h>
#include <media_player.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <unistd.h>

static const char* TAG = "audio_pb";

#define PB_TMP_PATH "/data/velaclaw/tts_play.pcm"
#define PB_OPTIONS_LEN 128

struct audio_playback {
    void* player;
    int tmp_fd;
    size_t total_written;
    unsigned int sample_rate;
    unsigned int channels;
    unsigned int bytes_per_sample;
};

audio_playback_t* audio_playback_open(const char* dev_path,
    unsigned int sample_rate, unsigned int channels,
    unsigned int bits_per_sample)
{
    (void)dev_path;

    audio_playback_t* pb = calloc(1, sizeof(*pb));

    if (!pb) {
        return NULL;
    }

    pb->tmp_fd = open(PB_TMP_PATH, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (pb->tmp_fd < 0) {
        syslog(LOG_ERR, "[%s] cannot create %s: %d\n",
            TAG, PB_TMP_PATH, errno);
        free(pb);
        return NULL;
    }

    pb->player = NULL;
    pb->total_written = 0;
    pb->sample_rate = sample_rate;
    pb->channels = channels;
    pb->bytes_per_sample = bits_per_sample / 8;

    syslog(LOG_INFO, "[%s] opened (%uHz %uch %ubit)\n",
        TAG, sample_rate, channels, bits_per_sample);
    return pb;
}

int audio_playback_write(audio_playback_t* pb,
    const void* buf, size_t len)
{
    if (!pb || pb->tmp_fd < 0 || !buf || len == 0) {
        return -EINVAL;
    }

    ssize_t n = write(pb->tmp_fd, buf, len);

    if (n > 0) {
        pb->total_written += (size_t)n;
    }

    return (int)n;
}

void audio_playback_close(audio_playback_t* pb)
{
    if (!pb) {
        return;
    }

    /* Finish writing temp file */
    if (pb->tmp_fd >= 0) {
        close(pb->tmp_fd);
        pb->tmp_fd = -1;
    }

    /* Play the file via media_player URL mode */
    char url[256];
    char opts[PB_OPTIONS_LEN];

    snprintf(url, sizeof(url), "file://%s", PB_TMP_PATH);
    snprintf(opts, sizeof(opts),
        "format=s%ule:sample_rate=%u:ch_layout=%s",
        VELACLAW_VOICE_BITS, VELACLAW_VOICE_SAMPLE_RATE,
        (VELACLAW_VOICE_CHANNELS == 1) ? "mono" : "stereo");

    void* player = media_player_open(MEDIA_STREAM_MUSIC);

    if (!player) {
        syslog(LOG_ERR, "[%s] media_player_open failed\n", TAG);
        goto out;
    }

    int ret = media_player_prepare(player, url, opts);

    if (ret < 0) {
        syslog(LOG_ERR, "[%s] prepare failed: %d\n", TAG, ret);
        media_player_close(player, 0);
        goto out;
    }

    ret = media_player_start(player);
    if (ret < 0) {
        syslog(LOG_ERR, "[%s] start failed: %d\n", TAG, ret);
        media_player_close(player, 0);
        goto out;
    }

    syslog(LOG_INFO, "[%s] playing %s (%zu bytes)\n",
        TAG, PB_TMP_PATH, pb->total_written);

    /* media_player_close(player, 1) does not reliably wait for
     * playback completion on all platforms.  Calculate the PCM
     * duration and sleep so the file stays readable until the
     * media framework finishes consuming it. Add 500ms margin
     * for buffering / scheduling latency. */

    if (pb->total_written > 0
        && pb->sample_rate > 0
        && pb->channels > 0
        && pb->bytes_per_sample > 0) {
        unsigned int bps = pb->sample_rate
            * pb->channels * pb->bytes_per_sample;
        unsigned int dur_ms = (unsigned int)((uint64_t)pb->total_written * 1000 / bps) + 500;

        syslog(LOG_INFO, "[%s] waiting %u ms for playback\n",
            TAG, dur_ms);
        usleep((useconds_t)dur_ms * 1000);
    }

    media_player_close(player, 0);
    syslog(LOG_INFO, "[%s] playback done\n", TAG);

out:
    unlink(PB_TMP_PATH);
    free(pb);
}
