   655	 * Name: nxplayer_filltone
   656	 *
   657	 *  Fill the generated tone data into the specified
   658	 *  buffer.
   659	 *
   660	 ****************************************************************************/
   661	
   662	static int nxplayer_filltone(FAR struct nxplayer_tone_s *tone,
   663	                             FAR struct ap_buffer_s *apb)
   664	{
   665	  FAR uint16_t *samples;
   666	  float value;
   667	  size_t i;
   668	
   669	  apb->nbytes = 0;
   670	  apb->curbyte = 0;
   671	  samples = (FAR uint16_t *)apb->samp;
   672	
   673	  if (tone->cur_samps >= tone->total_samps)
   674	    {
   675	      return -ENODATA;
   676	    }
   677	
   678	  for (i = 0; i < apb->nmaxbytes / 4; i++)
   679	    {
   680	      value = sinf(2 * M_PI * tone->pitch_freq *
   681	                   tone->cur_samps / tone->sample_rate);
   682	      samples[i * 2 + 1] = samples[i * 2] = (uint16_t)(value * 10000);
   683	
   684	      tone->cur_samps++;
   685	      apb->nbytes += 4;
   686	
   687	      if (tone->cur_samps >= tone->total_samps)
   688	        {
   689	          apb->flags |= AUDIO_APB_FINAL;
   690	          break;
   691	        }
   692	    }
   693	
   694	  return 0;
   695	}
