    49	int nxplayer_fill_common(int fd, FAR struct ap_buffer_s *apb)
    50	{
    51	  /* Read data into the buffer. */
    52	
    53	  apb->nbytes  = read(fd, apb->samp, apb->nmaxbytes);
    54	  apb->curbyte = 0;
    55	  apb->flags   = 0;
    56	
    57	  while (0 < apb->nbytes && apb->nbytes < apb->nmaxbytes)
    58	    {
    59	      int n   = apb->nmaxbytes - apb->nbytes;
    60	      int ret = read(fd, &apb->samp[apb->nbytes], n);
    61	
    62	      if (0 >= ret)
    63	        {
    64	          break;
    65	        }
    66	
    67	      apb->nbytes += ret;
    68	    }
    69	
    70	  if (apb->nbytes < apb->nmaxbytes)
    71	    {
    72	#if defined (CONFIG_DEBUG_AUDIO_INFO) || defined (CONFIG_DEBUG_AUDIO_ERROR)
    73	      int errcode = errno;
    74	
    75	      audinfo("Closing audio file, nbytes=%d errcode=%d\n",
    76	              apb->nbytes, errcode);
    77	#endif
    78	
    79	      /* Set a flag to indicate that this is the final buffer in the stream */
    80	
    81	      apb->flags |= AUDIO_APB_FINAL;
    82	
    83	#ifdef CONFIG_DEBUG_AUDIO_ERROR
    84	      /* Was this a file read error */
    85	
    86	      if (apb->nbytes == 0 && errcode != 0)
    87	        {
    88	          DEBUGASSERT(errcode > 0);
    89	          auderr("ERROR: fread failed: %d\n", errcode);
    90	        }
    91	#endif
    92	
    93	      return -ENODATA;
    94	    }
    95	
    96	  /* Return OK to indicate that the buffer should be passed through to the
    97	   * audio device.  This does not necessarily indicate that data was read
    98	   * correctly.
    99	   */
   100	
   101	  return OK;
   102	}
