    68	  val |= TX_DVC3_4_CTL_DVC3_EN;
    69	  writel(val, TX_DVC3_4_CTL_REG(haudio));
    70	  /* Enable IF */
    71	  val = readl(TX_PLAYBACK_CTL_REG(haudio));
    72	  val &= ~TX_PLAYBACK_CTL_IF_CH0_MASK;
    73	  val &= ~TX_PLAYBACK_CTL_IF_CH1_MASK;
    74	  val |= TX_PLAYBACK_CTL_PLAYBACK_IF_EN | TX_PLAYBACK_CTL_IF_CH0_EN |
    75	         TX_PLAYBACK_CTL_IF_CH1_EN;
    76	  writel(val, TX_PLAYBACK_CTL_REG(haudio));
    77	  /* Enable SDM0 */
    78	  val = readl(TX_SDM_CTL_REG(haudio));
    79	  val &= ~TX_SDM_CTL_TX_CH0_SDM_EN_MASK;
    80	  val |= TX_SDM_CTL_TX_CH0_SDM_EN;
    81	  writel(val, TX_SDM_CTL_REG(haudio));
    82	  /* Configure MIXER audio path */
    83	  val = readl(TX_MIXER_CTL_REG(haudio));
    84	  val &= ~TX_MIXER_CTL_MIXER0_PATH_MASK;
    85	  val |= TX_MIXER_CTL_MIXER0_AUDOUTL_SEL | TX_MIXER_CTL_MIXER1_AUDOUTR_SEL;
    86	  writel(val, TX_MIXER_CTL_REG(haudio));
    87	  /* Configure PWM0 single output */
    88	  val = readl(TX_PWM_CTL_REG(haudio));
    89	  val &= ~TX_PWM_CTL_PWM0_MODE_MASK;
    90	  val |= TX_PWM_CTL_PWM0_EN | TX_PWM_CTL_PWM0_FADE_EN;
    91	  /* Check output mode */
    92	  if (haudio->init.out_mode == AUDIO_OUTPUT_MODE_PDM)
    93	    val |= TX_PWM_CTL_PWM0_MODE_PDM;
    94	
    95	  writel(val, TX_PWM_CTL_REG(haudio));
    96	}
