    98	/**
    99	 * @brief Configures AUDIO for PWM1 single output mode.
   100	 *
   101	 *        This function sets up the audio hardware to use PWM1 as the single
   102	 * output channel. It enables the necessary digital volume control, interface,
   103	 * and sigma-delta modulator components, configures the mixer path, and sets
   104	 * PWM1 to single output mode.
   105	 *
   106	 * @param[in,out] haudio Pointer to AUDIO handle structure
   107	 *
   108	 * @note This function is internally used by the audio driver and should not be
   109	 * called directly. It assumes that the AUDIO handle has been properly
   110	 * initialized.
   111	 *
   112	 * @warning Do not call this function from an interrupt context.
   113	 */
   114	static void audio_set_pwm1(hal_audio_handle_t *haudio) {
   115	  uint32_t val;
   116	
   117	  if (!haudio)
   118	    return;
   119	  /* Enable DVC4 */
   120	  val = readl(TX_DVC3_4_CTL_REG(haudio));
   121	  val &= ~TX_DVC3_4_CTL_DVC4_MASK;
   122	  val |= TX_DVC3_4_CTL_DVC4_EN;
   123	  writel(val, TX_DVC3_4_CTL_REG(haudio));
   124	  /* Enable IF */
   125	  val = readl(TX_PLAYBACK_CTL_REG(haudio));
   126	  val &= ~TX_PLAYBACK_CTL_IF_CH0_MASK;
   127	  val &= ~TX_PLAYBACK_CTL_IF_CH1_MASK;
   128	  val |= TX_PLAYBACK_CTL_PLAYBACK_IF_EN | TX_PLAYBACK_CTL_IF_CH0_EN |
   129	         TX_PLAYBACK_CTL_IF_CH1_EN;
   130	  writel(val, TX_PLAYBACK_CTL_REG(haudio));
   131	  /* Enable SDM1 */
   132	  val = readl(TX_SDM_CTL_REG(haudio));
   133	  val &= ~TX_SDM_CTL_TX_CH1_SDM_EN_MASK;
   134	  val |= TX_SDM_CTL_TX_CH1_SDM_EN;
   135	  writel(val, TX_SDM_CTL_REG(haudio));
   136	  /* Configure MIXER audio path */
   137	  val = readl(TX_MIXER_CTL_REG(haudio));
   138	  val &= ~TX_MIXER_CTL_MIXER1_PATH_MASK;
   139	  val |= TX_MIXER_CTL_MIXER0_AUDOUTR_SEL | TX_MIXER_CTL_MIXER1_AUDOUTL_SEL;
   140	  writel(val, TX_MIXER_CTL_REG(haudio));
   141	  /* Configure PWM1 single output */
   142	  val = readl(TX_PWM_CTL_REG(haudio));
   143	  val &= ~TX_PWM_CTL_PWM1_MODE_MASK;
   144	  val |= TX_PWM_CTL_PWM1_EN | TX_PWM_CTL_PWM1_FADE_EN;
   145	  /* Check output mode */
   146	  if (haudio->init.out_mode == AUDIO_OUTPUT_MODE_PDM)
   147	    val |= TX_PWM_CTL_PWM1_MODE_PDM;
   148	
   149	  writel(val, TX_PWM_CTL_REG(haudio));
   150	}
