   152	/**
   153	 * @brief Configures AUDIO output channels based on initialization parameters.
   154	 *
   155	 *        This function selects and configures the appropriate output channels
   156	 *        according to the output_chan parameter in the AUDIO initialization
   157	 * structure. It supports various configurations including single channel, dual
   158	 * channel, and differential outputs.
   159	 *
   160	 * @param[in,out] haudio Pointer to AUDIO handle structure
   161	 *
   162	 * @note This function is internally used by the audio driver and should not be
   163	 * called directly. It assumes that the AUDIO handle has been properly
   164	 * initialized.
   165	 *
   166	 * @warning Do not call this function from an interrupt context.
   167	 */
   168	static void audio_set_channel(hal_audio_handle_t *haudio) {
   169	  uint32_t val;
   170	
   171	  if (!haudio)
   172	    return;
   173	  /* Set PWM channel */
   174	  switch (haudio->init.output_chan) {
   175	  case AUDIO_OUTPUT_CHAN_PWM1:
   176	    audio_set_pwm1(haudio);
   177	    break;
   178	  case AUDIO_OUTPUT_CHAN_PWM0_PWM1:
   179	    audio_set_pwm0(haudio);
   180	    audio_set_pwm1(haudio);
   181	    break;
   182	  case AUDIO_OUTPUT_CHAN_PWM0_DIFF:
   183	    audio_set_pwm0(haudio);
   184	    audio_set_pwm1(haudio);
   185	    val = readl(TX_PWM_CTL_REG(haudio));
   186	    val &= ~(TX_PWM_CTL_PWM0_MODE_MASK | TX_PWM_CTL_PWM1_MODE_MASK);
   187	    val |= TX_PWM_CTL_PWM0_EN | TX_PWM_CTL_PWM0_DIF_EN;
   188	    writel(val, TX_PWM_CTL_REG(haudio));
   189	    break;
   190	  case AUDIO_OUTPUT_CHAN_PWM1_DIFF:
   191	    audio_set_pwm0(haudio);
   192	    audio_set_pwm1(haudio);
   193	    val = readl(TX_PWM_CTL_REG(haudio));
   194	    val &= ~(TX_PWM_CTL_PWM0_MODE_MASK | TX_PWM_CTL_PWM1_MODE_MASK);
   195	    val |= TX_PWM_CTL_PWM1_EN | TX_PWM_CTL_PWM1_DIF_EN;
   196	    writel(val, TX_PWM_CTL_REG(haudio));
   197	    break;
   198	  case AUDIO_OUTPUT_CHAN_PWM0:
   199	  default:
   200	    audio_set_pwm0(haudio);
   201	    break;
   202	  }
   203	}
