   332	/**
   333	 * @brief Configures AUDIO sampling rate based on initialization parameters.
   334	 *
   335	 *        This function sets the appropriate hardware divider values and clock
   336	 * frequencies according to the samplerate parameter in the AUDIO initialization
   337	 * structure. It ensures that the audio hardware operates at the correct
   338	 * sampling frequency.
   339	 *
   340	 * @param[in,out] haudio Pointer to AUDIO handle structure
   341	 *
   342	 * @note This function is internally used by the audio driver and should not be
   343	 * called directly. It assumes that the AUDIO handle has been properly
   344	 * initialized.
   345	 *
   346	 * @warning Do not call this function from an interrupt context.
   347	 */
   348	void hal_audio_set_samplerate(hal_audio_handle_t *haudio) {
   349	  uint32_t val, module_freq, hw_rate = 0;
   350	
   351	  if (!haudio)
   352	    return;
   353	  /* Get frequency division factor */
   354	  switch (haudio->init.samplerate) {
   355	  case AUDIO_SAMPLERATE_48000:
   356	  case AUDIO_SAMPLERATE_44100:
   357	    hw_rate = 0;
   358	    break;
   359	  case AUDIO_SAMPLERATE_32000:
   360	    hw_rate = 1;
   361	    break;
   362	  case AUDIO_SAMPLERATE_24000:
   363	  case ADUIO_SAMPLERATE_22050:
   364	    hw_rate = 2;
   365	    break;
   366	  case ADUIO_SAMPLERATE_16000:
   367	    hw_rate = 3;
   368	    break;
   369	  case ADUIO_SAMPLERATE_11025:
   370	  case ADUIO_SAMPLERATE_12000:
   371	    hw_rate = 4;
   372	    break;
   373	  case ADUIO_SAMPLERATE_8000:
   374	    hw_rate = 5;
   375	    break;
   376	  default:
   377	    break;
   378	  }
   379	  /* Set playback samplerate */
   380	  val = readl(TX_PLAYBACK_CTL_REG(haudio));
   381	  val &= ~TX_PLAYBACK_CTL_FS_OUT_MASK;
   382	  val |= TX_PLAYBACK_CTL_FS_OUT(hw_rate);
   383	  writel(val, TX_PLAYBACK_CTL_REG(haudio));
   384	
   385	  /* Set DMIC samplerate */
   386	  val = readl(RX_DMIC_IF_CTRL_REG(haudio));
   387	  val &= ~RX_DMIC_IF_FS_IN_MASK;
   388	  val |= RX_DMIC_IF_FS_IN(hw_rate);
   389	  writel(val, RX_DMIC_IF_CTRL_REG(haudio));
   390	
   391	  /* Get module frequency */
   392	  switch (haudio->init.samplerate) {
   393	  case AUDIO_SAMPLERATE_48000:
   394	  case AUDIO_SAMPLERATE_32000:
   395	  case AUDIO_SAMPLERATE_24000:
   396	  case ADUIO_SAMPLERATE_16000:
   397	  case ADUIO_SAMPLERATE_12000:
   398	  case ADUIO_SAMPLERATE_8000:
   399	    val = readl(TX_PLAYBACK_CTL_REG(haudio));
   400	    val &= ~TX_PLAYBACK_CTL_CLK_MASK;
   401	    writel(val, TX_PLAYBACK_CTL_REG(haudio));
   402	
   403	    val = readl(RX_DMIC_IF_CTRL_REG(haudio));
   404	    val &= ~RX_DMIC_IF_RX_CLK_MASK;
   405	    writel(val, RX_DMIC_IF_CTRL_REG(haudio));
   406	
   407	    module_freq = AUDIO_FREQ_24576000;
   408	    break;
   409	  case AUDIO_SAMPLERATE_44100:
   410	  case ADUIO_SAMPLERATE_22050:
   411	  case ADUIO_SAMPLERATE_11025:
   412	    val = readl(TX_PLAYBACK_CTL_REG(haudio));
   413	    val |= TX_PLAYBACK_CTL_CLK_22579KHZ;
   414	    writel(val, TX_PLAYBACK_CTL_REG(haudio));
   415	
   416	    val = readl(RX_DMIC_IF_CTRL_REG(haudio));
   417	    val |= RX_DMIC_IF_RX_CLK_22579KHZ;
   418	    writel(val, RX_DMIC_IF_CTRL_REG(haudio));
   419	
   420	    module_freq = AUDIO_FREQ_22579200;
   421	    break;
   422	  default:
   423	    module_freq = 0;
   424	  }
   425	  hal_clk_set_freq(CLK_AUDIO_SCLK, module_freq);
   426	}
