   483	/**
   484	 * @brief Initializes the AUDIO peripheral with specified parameters.
   485	 *
   486	 *        This function fully initializes the AUDIO peripheral according to the
   487	 * parameters specified in the AUDIO handle structure. It configures all
   488	 * hardware registers, sets up the audio path, and prepares the peripheral for
   489	 * data transmission.
   490	 *
   491	 * @param[in,out] haudio Pointer to AUDIO handle structure containing
   492	 * initialization parameters
   493	 *
   494	 * @return HAL_OK on successful initialization, HAL_ERROR if parameters are
   495	 * invalid, HAL_BUSY if AUDIO is busy
   496	 *
   497	 * @note This function requires that the init_cb callback is registered to
   498	 * configure clocks. The samplebits, samplerate, and channel parameters must be
   499	 * set by the application.
   500	 *
   501	 * @warning Do not call this function from an interrupt context.
   502	 */
   503	hal_status_e hal_audio_init(hal_audio_handle_t *haudio) {
   504	  uint32_t val, fade_val;
   505	  uint16_t target_vol;
   506	
   507	  if (!haudio)
   508	    return HAL_ERROR;
   509	
   510	  ASSERT_PARAM(0 != (haudio->init.flag & HAL_HANDLE_ALL_INIT_FLAG));
   511	  ASSERT_PARAM(haudio->regbase != 0);
   512	
   513	  HAL_LOCK(haudio);
   514	  if (haudio->init_cb)
   515	    /* Should set input frequency and enable clock for AUDIO in callback */
   516	    haudio->init_cb(haudio);
   517	  else {
   518	    hal_audio_clock_init();
   519	  }
   520	  /* Set audio volume */
   521	  if (haudio->init.target_volume != ADUIO_DEFAULT_TAR_VOLUME) {
   522	    target_vol = ADUIO_DEFAULT_TAR_VOLUME - haudio->init.target_volume;
   523	    if (target_vol == 100)
   524	      fade_val = 0;
   525	    else
   526	      fade_val = AUDIO_DEFAULT_FADE_VOL - (target_vol * AUDIO_DEFAULT_FADE_MAP);
   527	    val = readl(FADE_CTL1_REG(haudio));
   528	    val &= ~FADE_CTL1_TARGET_VOL_MASK;
   529	    val |= fade_val;
   530	    writel(val, FADE_CTL1_REG(haudio));
   531	  }
   532	  /* Set fade step */
   533	  if (haudio->init.fade_step != AUDIO_DEFAULT_FADE_STEP) {
   534	    val = readl(FADE_CTL0_REG(haudio));
   535	    val &= ~FADE_CTL0_FADE_STEP_MASK;
   536	    val |= haudio->init.fade_step;
   537	    writel(val, FADE_CTL0_REG(haudio));
   538	  }
   539	  /* Set fade speed */
   540	  if (haudio->init.fade_speed != AUDIO_DEFAULT_FADE_SPEED) {
   541	    val = readl(FADE_CTL0_REG(haudio));
   542	    val &= ~FADE_CTL0_FADE_SPEED_MASK;
   543	    val |= haudio->init.fade_speed;
   544	    writel(val, FADE_CTL0_REG(haudio));
   545	  }
   546	  /* Set DVC gain */
   547	  if (haudio->init.dvc_volume != AUDIO_DEFAULT_DVC_VOLUME) {
   548	    val = readl(TX_DVC3_4_CTL_REG(haudio));
   549	    val &= ~TX_DVC3_4_CTL_DVC3_GAIN_MASK;
   550	    val &= ~TX_DVC3_4_CTL_DVC4_GAIN_MASK;
   551	    val |= (haudio->init.dvc_volume << TX_DVC3_4_CTL_DVC3_GAIN_SHIFT |
   552	            haudio->init.dvc_volume << TX_DVC3_4_CTL_DVC4_GAIN_SHIFT);
   553	    writel(val, TX_DVC3_4_CTL_REG(haudio));
   554	  }
   555	  /* Set filter shift */
   556	  if (haudio->init.fltout_shift != AUDIO_FLTOUT_SHIFT_13BIT) {
   557	    val = readl(TX_PLAYBACK_CTL_REG(haudio));
   558	    val &= ~TX_PLAYBACK_CTL_FLTOUT_SHIFTN_MASK;
   559	    val |= haudio->init.fltout_shift << TX_PLAYBACK_CTL_FLTOUT_SHIFTN_SHIFT;
   560	    writel(val, TX_PLAYBACK_CTL_REG(haudio));
   561	  }
   562	  /* Set output and check output mode */
   563	  audio_set_channel(haudio);
   564	  /* Set SDM gain */
   565	  if (haudio->init.sdm_gain != AUDIO_SDM_GAIN_1) {
   566	    val = readl(TX_SDM_CTL_REG(haudio));
   567	    val &= ~(TX_SDM_CTL_TX_CH0_SDM_GAIN_A0_MASK |
   568	             TX_SDM_CTL_TX_CH0_SDM_GAIN_B0_MASK |
   569	             TX_SDM_CTL_TX_CH0_SDM_GAIN_C0_MASK |
   570	             TX_SDM_CTL_TX_CH1_SDM_GAIN_A0_MASK |
   571	             TX_SDM_CTL_TX_CH1_SDM_GAIN_B0_MASK |
   572	             TX_SDM_CTL_TX_CH1_SDM_GAIN_C0_MASK);
   573	    val |= (haudio->init.sdm_gain << TX_SDM_CTL_TX_CH0_SDM_GAIN_A0_SHIFT |
   574	            haudio->init.sdm_gain << TX_SDM_CTL_TX_CH0_SDM_GAIN_B0_SHIFT |
   575	            haudio->init.sdm_gain << TX_SDM_CTL_TX_CH0_SDM_GAIN_C0_SHIFT |
   576	            haudio->init.sdm_gain << TX_SDM_CTL_TX_CH1_SDM_GAIN_A0_SHIFT |
   577	            haudio->init.sdm_gain << TX_SDM_CTL_TX_CH1_SDM_GAIN_B0_SHIFT |
   578	            haudio->init.sdm_gain << TX_SDM_CTL_TX_CH1_SDM_GAIN_C0_SHIFT);
   579	    writel(val, TX_SDM_CTL_REG(haudio));
   580	  }
   581	  /* Check samplebits */
   582	  if (haudio->init.samplebits != AUDIO_SAMPLEBITS_16BIT) {
   583	    haudio->errcode = AUDIO_ERROR_INVALID_PARAM;
   584	    return HAL_ERROR;
   585	  }
   586	  /* Set samplerate */
   587	  hal_audio_set_samplerate(haudio);
   588	  /* Set output channel num */
   589	  val = readl(TXFIFO_CTL_REG(haudio));
   590	  val &= ~(TXFIFO_CTL_TX_FIFO_CH0_EN_MASK | TXFIFO_CTL_TX_FIFO_CH1_EN_MASK);
   591	  /* Maybe need to check the channel num, now is all fifo open */
   592	  val |= TXFIFO_CTL_TX_FIFO_CH0_EN | TXFIFO_CTL_TX_FIFO_CH1_EN;
   593	  writel(val, TXFIFO_CTL_REG(haudio));
   594	  /*Flush TXFIFO*/
   595	  val = readl(TXFIFO_CTL_REG(haudio));
   596	  val |= TXFIFO_CTL_TX_FIFO_FLUSH_MASK;
   597	  val = readl(TXFIFO_CTL_REG(haudio));
   598	
   599	  haudio->errcode = AUDIO_ERROR_NONE;
   600	  haudio->state = AUDIO_STATE_READY;
   601	  HAL_UNLOCK(haudio);
   602	
   603	  return HAL_OK;
   604	}
