   520	static int aic_audio_start(FAR struct audio_lowerhalf_s *dev) {
   521	  struct aic_audio_s *priv = (struct aic_audio_s *)dev;
   522	
   523	  if (priv->started) {
   524	    return OK;
   525	  }
   526	
   527	  priv->tone_phase = 0;
   528	  priv->xrun = false;
   529	
   530	  if (priv->alloc_addr == NULL) {
   531	    auderr("audio start failed: no dma buffers allocated\n");
   532	    return -ENOMEM;
   533	  }
   534	
   535	  if (dq_empty(&priv->pendq)) {
   536	    auderr("audio start failed: no queued buffers\n");
   537	    return -EAGAIN;
   538	  }
   539	
   540	  audwarn("audio start rate=%u channels=%u hw_channels=%u samplebits=%u "
   541	          "period=%u fifo=%u\n",
   542	          (unsigned int)priv->samplerate, priv->channels,
   543	          (unsigned int)AIC_AUDIO_PHY_CHANNELS, priv->samplebits,
   544	          (unsigned int)priv->buffer_size,
   545	          (unsigned int)(priv->buffer_size * priv->buffer_num));
   546	
   547	  priv->audio.init.samplerate = (hal_audio_samplerate_e)priv->samplerate;
   548	  priv->audio.init.channel =
   549	      priv->channels == 1 ? AUDIO_CHANNEL_MONO : AUDIO_CHANNEL_STEREO;
   550	  priv->audio.init.samplebits = AUDIO_SAMPLEBITS_16BIT;
   551	  priv->audio.init.output_chan = aic_audio_output_channel();
   552	  priv->audio.txdma = aic_audio_use_cpu_tx() ? NULL : &priv->txdma_chan.hal;
   553	
   554	  if (!aic_audio_use_cpu_tx()) {
   555	    hal_dma_handle_t *hdma = priv->audio.txdma;
   556	    hdma->parent = &priv->audio;
   557	    hdma->regbase = DMA_BASE;
   558	    hdma->init.channel_id = 0;
   559	    hdma->work_mode = DMA_WORK_MODE_NORMAL;
   560	    hdma->cyclic_period_len = 0;
   561	    hdma->init.direction = DMA_MEMORY_TO_DEVICE;
